24	uint32_t AiInfraFusedInferAttentionSinkMetadataKernel::Compute(CpuKernelContext &ctx)
25	{
26	    bool success = Prepare(ctx);
27	    if (!success) {
28	        return KERNEL_STATUS_PARAM_INVALID;
29	    }
30	    CheckIsMla();
31	    cvRatio_ = aivCoreNum_ / aicCoreNum_;
32	    if (s2Size == 0) {
33	        /*
34	         * 1024，空tensor场景下，作为默认值完成后续计算
35	         * 避免matmal tiling  softmax tiling异常
36	         * kernel计算使用真实的seqSize=0, 与actuseq_len流程归一
37	         */
38	        s2Size = 1024;
39	    }
40	    BaseInfo baseInfo{};
41	    SplitParam splitParam{};
42	    if (isMlaSink) {
43	        CalcInnerSizeMla(static_cast<uint32_t>(s2Size));
44	        CreateSplitInputMla(baseInfo, splitParam);
45	    } else {
46	        CalcInnerSizeGqa(static_cast<uint32_t>(s2Size));
47	        CreateSplitInputGqa(baseInfo, splitParam);
48	    }
49	    SplitResult res{aicCoreNum_, cvRatio_};
50	    SplitCore(aicCoreNum_, baseInfo, splitParam, res);
51	    if (res.numOfFdHead > aicCoreNum_ || res.usedCoreNum > aicCoreNum_ || res.maxS2SplitNum > aicCoreNum_ + 1) {
52	        KERNEL_LOG_ERROR("used_core_num: %u, num_of_fd_head: %u, max_s2_split_num: %u, aic_num: %u",
53	                         res.usedCoreNum,
54	                         res.numOfFdHead,
55	                         res.maxS2SplitNum,
56	                         aicCoreNum_);
57	    }
58	    success = GenMetaData(res);
59	    return success ? KERNEL_STATUS_OK : KERNEL_STATUS_PARAM_INVALID;
60	}
