62	bool AiInfraFusedInferAttentionSinkMetadataKernel::GenMetaData(const SplitResult &splitRes)
63	{
64	    optiling::detail::FiaSinkMetaData *metaDataPtr = (optiling::detail::FiaSinkMetaData *)metaData_->GetData();
65	    // aic Metadata Generate
66	    for (uint32_t i = 0; i < splitRes.usedCoreNum; ++i) {
67	        if (i >= splitRes.usedCoreNum) {
68	            metaDataPtr->aicMetadata[i][AIC_CORE_ENABLE_INDEX] = 0; // AIC disenable
69	            continue;
70	        }
71	        metaDataPtr->aicMetadata[i][AIC_CORE_ENABLE_INDEX] = 1; // AIC enable
72	        metaDataPtr->aicMetadata[i][BN2_END_PTR_INDEX] = splitRes.bN2End[i];
73	        metaDataPtr->aicMetadata[i][GS1_END_PTR_INDEX] = splitRes.gS1End[i];
74	        metaDataPtr->aicMetadata[i][S2_END_PTR] = splitRes.s2End[i];
75	        metaDataPtr->aicMetadata[i][BN2_IDX_OF_FD_HEAD_INDEX] = splitRes.fdRes.bN2IdxOfFdHead[i];
76	        metaDataPtr->aicMetadata[i][GS1_IDX_OF_FD_HEAD_INDEX] = splitRes.fdRes.gS1IdxOfFdHead[i];
77	        metaDataPtr->aicMetadata[i][S2_SPLIT_NUM_OF_FD_HEAD_INDEX] = splitRes.fdRes.s2SplitNumOfFdHead[i];
78	        metaDataPtr->aicMetadata[i][S2_SPLIT_START_IDX_OF_CORE_INDEX] = splitRes.fdRes.s2SplitStartIdxOfCore[i];
79	        metaDataPtr->aicMetadata[i][GS1_SPLIT_NUM_OF_FD_HEAD_INDEX] = splitRes.fdRes.gS1SplitNumOfFdHead[i];
80	        metaDataPtr->aicMetadata[i][GS1_LAST_PART_SIZE_OF_FD_HEAD_INDEX] = splitRes.fdRes.gS1LastPartSizeOfFdHead[i];
81	    }
82	
83	    // aiv Metadata Generate,当前仅支持C:V=1:2
84	    for (uint32_t i = 0; i < splitRes.usedCoreNum * 2; ++i) {
85	        if (i >= (splitRes.usedCoreNum * 2)) {
86	            metaDataPtr->aivMetadata[i][AIV_CORE_ENABLE_INDEX] = 0; // AIV disenable
87	            continue;
88	        }
89	        metaDataPtr->aivMetadata[i][AIV_CORE_ENABLE_INDEX] = 1; // AIV enable
90	        metaDataPtr->aivMetadata[i][GS1_IDX_END_OF_FD_HEAD_INDEX] = splitRes.fdRes.gS1IdxEndOfFdHead[i];
91	        metaDataPtr->aivMetadata[i][GS1_IDX_END_OF_FD_HEAD_SPLIT_INDEX] = splitRes.fdRes.gS1IdxEndOfFdHeadSplit[i];
92	    }
93	
94	    for (size_t i = 0; i < BASE_METADATA_SIZE; ++i) {
95	        metaDataPtr->baseMetadata[M_BASE_SIZE_INDEX] = mBaseSize_;
96	        metaDataPtr->baseMetadata[S_INNER_SIZE_INDEX] = sInnerSize_;
97	        metaDataPtr->baseMetadata[M_FD_BASE_SIZE_INDEX] = mFdBaseSize_;
98	        metaDataPtr->baseMetadata[NUM_OF_FD_INDEX] = splitRes.numOfFdHead;
99	        metaDataPtr->baseMetadata[USED_CORE_NUM_INDEX] = splitRes.usedCoreNum;
100	        metaDataPtr->baseMetadata[USED_VEC_NUM_OF_FD_INDEX] = splitRes.usedVecNumOfFd;
101	        metaDataPtr->baseMetadata[S1_SIZE_INDEX] = s1Size;
102	        metaDataPtr->baseMetadata[S2_SIZE_INDEX] = s2Size;
103	        metaDataPtr->baseMetadata[ACUTAL_LEN_Q_DIM_INDEX] = actualLenQDims;
104	        metaDataPtr->baseMetadata[ACUTAL_LEN_KV_DIM_INDEX] = actualLenKvDims;
105	    }
106	    return true;
107	}
