109	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcInnerSizeMla(uint32_t seqSize)
110	{
111	    /*
112	     * CANN reduceSum函数在规约长度S  S>=512、S<512两种场景内部实现的累加顺序不同，
113	     * 为了保障batchInvariant场景计算结果的一致性，将算子在S2方向的基本块大小固定为256，
114	     * 从而确保不同shape下reduceSum函数的累加序的一致性
115	    */
116	    if (batchInvariant_) {
117	        sInnerSize_ = 256U;
118	    } else {
119	        sInnerSize_ = 512U;
120	        uint32_t s1G = s1Size * gSize;
121	        /*
122	         * BAND场景，带上sinkToken后，分块位置发生变化，从而导致计算band边界覆盖的基本块增加，导致无效计算量增大
123	         * 将基本块大小减小至256，减少无效计算量，缓解极端场景下分核劣势
124	         * s1G >= 128为实测最优值
125	        */
126	        if (sinkNum_ > 0 && sinkNum_ <= 256 && sparseMode_ == static_cast<uint32_t>(SparseMode::BAND) && s1G >= 128) {
127	            // decode阶段sparseMode4场景sinkToken耗时优化，s1G >= 128经验值
128	            sInnerSize_ = 256;
129	        }
130	
131	        /*
132	         * 在decode阶段 sinkTensor场景，使得小batch时尽可能使用满核数
133	         * 在SWA阶段，窗口大小为512时，单batch在s2base=512时，分3个核，
134	         * 在s2base=256时分4个核，batch=6时，刚好用满24个核。
135	        */
136	        if ((kSinkNum_ > 0 && (sparseMode_ == static_cast<uint32_t>(SparseMode::BAND)) && 
137	            bSize <= 6 && (preToken + nextToken < 512))) {
138	            sInnerSize_ = 256;
139	        }
140	
141	        // FlashDecode时，如果S2的计算量>=256(确保切分后不小于128)但又不足以分2次计算时，则修改sInnerSize_，均分为2份进行计算，确保Nbuffer=2
142	        if (splitKVFlag_ && inputLayout_ != "TND") {
143	            if (seqSize == 256U) {
144	                sInnerSize_ = 128U;
145	            } else if (seqSize > 256U && seqSize <= sInnerSize_) {
146	                sInnerSize_ = (sInnerSize_ + 1U) / 2U;
147	            }
148	        }
149	
150	        // PA特性泛化场景，blockSize可能为112等值，无法被sInnerSize_整除，当step*base跨block时，搬运处理复杂，通过向下对齐避免
151	        if (blockSize_ != 0) {
152	            uint32_t blockSize = static_cast<uint32_t>(blockSize_);
153	            if ((sInnerSize_ > blockSize) && (sInnerSize_ % blockSize != 0)) {
154	                sInnerSize_ = (sInnerSize_ / blockSize) * blockSize;
155	            }
156	        }
157	
158	        sInnerLoopTimes_ = (seqSize + sInnerSize_ - 1U) / sInnerSize_;
159	        sInnerSizeTail_ = seqSize - (sInnerLoopTimes_ - 1U) * sInnerSize_;
160	        // tiling下沉 && flash decoder场景时，sInnerSize_基块大小不按照真实值修改
161	        // 否则会导致 tiling下沉 && flash decoder 场景时开辟workspace空间大小小于真实运行时所需的workspace大小
162	        if (sInnerSize_ > seqSize) {
163	            sInnerSize_ = seqSize;
164	        }
165	    }
166	    sInnerSizeAlign_ = Align(sInnerSize_, BYTE_BLOCK); // 元素个数按照基本块大小对齐
167	
168	    CalcMBaseSizeMla();
169	}
