171	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcMBaseSizeMla()
172	{
173	    if (batchInvariant_) {
174	        uint32_t mBaseSizeBatchInvariant = 256;
175	        mBaseSize_ = mBaseSizeBatchInvariant;
176	        return;
177	    }
178	
179	    uint32_t bN2 = bSize * n2Size;
180	    uint32_t s1G = s1Size * gSize;
181	    if (bN2 == 0U || aicCoreNum_ == 0U) {
182	        return;
183	    }
184	    // 若BN2能整除核数或者KVS不等长，不考虑调整mBaseSize
185	    if (bN2 % aicCoreNum_ == 0U || !DealSameSeqEachBatch()) {
186	        return;
187	    }
188	
189	    // 求B*N2与核数的最小公倍数
190	    uint32_t originalA = bN2;
191	    uint32_t originalB = aicCoreNum_;
192	    // 欧几里得算法计算最大公约数
193	    while (originalB != 0U) {
194	        originalA %= originalB;
195	        std::swap(originalA, originalB);
196	    }
197	
198	    // 计算最小公倍数
199	    uint32_t lcm = (bN2 / originalA) * aicCoreNum_;
200	    uint32_t splitOfS1G = lcm / bN2; // 求S1G被切多少份，可以不开FD
201	    // 如果不能等分S1G，则不切S2无法做到负载不均衡，不修改mBaseSize，直接按照最大mBaseSize进行切分
202	    if (splitOfS1G == 0U || s1G % splitOfS1G != 0U) {
203	        return;
204	    }
205	    uint32_t mBaseSizeTmp = s1G / splitOfS1G; // 计算可以等分S1G的mBaseSize
206	    // 128：最小的mBaseSize，计算的理论mBaseSize需要在原定mBaseSize和最小mBaseSize区间内
207	    if (mBaseSizeTmp > mBaseSize_ || mBaseSizeTmp < 128U) {
208	        return;
209	    }
210	
211	    mBaseSize_ = mBaseSizeTmp; // 满足以上条件则更新mBaseSize
212	}
