214	void AiInfraFusedInferAttentionSinkMetadataKernel::CreateSplitInputMla(BaseInfo &baseInfo, SplitParam &splitParam) const
215	{
216	    // 构造分核输入参数
217	    baseInfo.bSize = bSize;
218	    baseInfo.n2Size = n2Size;
219	    baseInfo.gSize = gSize;
220	    baseInfo.s2Size = static_cast<uint32_t>(s2Size);
221	    baseInfo.s1Size = s1Size;
222	    baseInfo.actualLenQDims = actualLenQDims;
223	    baseInfo.actualLenKvDims = actualLenKvDims;
224	    baseInfo.preToken = preToken;
225	    baseInfo.nextToken = nextToken;
226	    baseInfo.isS1G = inputLayout_ == "TND" || inputLayout_ == "BSH_BSND";
227	    baseInfo.sparseMode = sparseMode_;
228	    baseInfo.attenMaskFlag = attenMaskFlag;
229	    baseInfo.sinkNumber = sinkNum_;
230	    baseInfo.keySinkNumber = kSinkNum_;
231	    baseInfo.supportFD = true;  // sink做为独立tensor传入时,decode默认走FD
232	    baseInfo.batchInvariant = batchInvariant_;
233	    if (actualSeqLengths_ != nullptr) {
234	        baseInfo.isAccumSeqS1 = isAccumQSeq;
235	        baseInfo.actualSeqS1Size.reserve(bSize);
236	        const int64_t *s1Ptr = static_cast<const int64_t *>(actualSeqLengths_->GetData());
237	        for (uint32_t i = 0; i < bSize; ++i) {
238	            baseInfo.actualSeqS1Size.emplace_back(s1Ptr[i]);
239	        }
240	    }
241	    if (actualSeqLengthsKv_ != nullptr) {
242	        baseInfo.isAccumSeqS2 = isAccumKVSeq;
243	        baseInfo.actualSeqS2Size.reserve(bSize);
244	        const int64_t *s2Ptr = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
245	        for (uint32_t i = 0; i < bSize; ++i) {
246	            baseInfo.actualSeqS2Size.emplace_back(s2Ptr[i]);
247	        }
248	    }
249	    splitParam.mBaseSize = mBaseSize_;
250	    splitParam.s2BaseSize = sInnerSize_;
251	    splitParam.gS1BaseSizeOfFd = mFdBaseSize_;
252	}
