254	bool AiInfraFusedInferAttentionSinkMetadataKernel::DealSameSeqEachBatch()
255	{
256	    batchContinuousFlag = blockSize_ == 0 ? true : false;
257	    if (batchContinuousFlag) {
258	        if (actualSeqLenFlag) {
259	            return isSameActualseq;
260	        } else {
261	            return isSameSeqAllKVTensor;
262	        }
263	    } else {
264	        return isSameActualseq;
265	    }
266	}
