268	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcInnerSizeGqa(uint32_t s2Size)
269	{
270	    /*
271	     * CANN reduceSum函数在规约长度S  S>=512、S<512两种场景内部实现的累加顺序不同，
272	     * 为了保障batchInvariant场景计算结果的一致性，将算子在S2方向的基本块大小固定为256，
273	     * 从而确保不同shape下reduceSum函数的累加序的一致性
274	    */
275	    if (batchInvariant_) {
276	        sInnerSize_ = 256;
277	    } else {
278	        if (inputLayout_ == "TND" || inputLayout_ == "NTD") {
279	            sInnerSize_ = S_INNER_SIZE_512;
280	            /*
281	             * BAND场景，带上sinkToken后，分块位置发生变化，从而导致计算band边界覆盖的基本块增加，导致无效计算量增大
282	             * 将基本块大小减小至256，减少无效计算量，缓解极端场景下分核劣势
283	            */
284	            if ((sinkNum_ > 0 && sinkNum_ <= 256 && s1Size > S1_SIZE_16 && 
285	                sparseMode_ == static_cast<uint32_t>(SparseMode::BAND))) {
286	                sInnerSize_ = 256;
287	            }
288	
289	            /*
290	             * prefill阶段，SWA场景(窗口大小为512)，针对sinkTensor场景做了小块跳过性能优化操作，需要将s2基本块修改为256
291	             * 由于prefill阶段数据量较大，在长序列场景为计算bound，跳过操作的搬运收益拿不到
292	             * 且将s2基本块修改为256后，scale操作增多，性能反而劣化，实验测试边界值为qTSize=32k
293	             * 
294	             * kernel侧使用的sInnerSize_是通过aicpu传递的，该处的sInnerSize_不起作用
295	             * 该处和aicpu的差异在于，该处使用qTSize，aicpu使用actseqlen[-1]
296	            */
297	            const int64_t *s1Ptr = static_cast<const int64_t*>(actualSeqLengths_->GetData());
298	            if ((kSinkNum_ > 0 && sparseMode_ == static_cast<uint32_t>(SparseMode::BAND) && 
299	                s1Ptr[bSize - 1] < 32 * 1024 && (preToken + nextToken < 512))) {
300	                sInnerSize_ = 256;
301	            }
302	        } else {
303	            if (s1Size <= S1_SIZE_16) {
304	                /**
305	                * V1阶段分配用于存放mm1结果的UB大小为32K, 当计算的数据类型为float时，其可以存放8192个元素.
306	                * 另外, 需要保证单次计算不会切分S2, 那么S2的内切大小最大为8192, 所以将默认值设置为8192
307	                */
308	                sInnerSize_ = MAX_SPLIT_SIZE; // 8192
309	
310	                /** 当前版本限制workspace大小不超过32MB，否则会影响网络中前后算子性能，
311	                *  GQA场景下 nNumOfQInOneGroup和sInnerSize_切分大小直接影响workspace大小,
312	                *  具体计算参考CalcWorkSpace函数，这里根据nNumOfQInOneGroup将sInnerSize_
313	                *  分为8192，4096，2048三档，nNumOfQInOneGroup增大时减小sInnerSize_，
314	                *   保证最终workspace大小不超过32MB。
315	                */
316	                uint32_t sInnerSize[3U] = {8192U, 4096U, 2048U};
317	                uint32_t idx = std::min(gSize / 5U, 2U);
318	                sInnerSize_ = sInnerSize[idx];
319	            } else {
320	                sInnerSize_ = S_INNER_SIZE_512;
321	            }
322	        }
323	        if (attenMaskFlag && (sparseMode_ == static_cast<uint32_t>(SparseMode::LEFT_UP_CAUSAL) ||
324	                sparseMode_ == static_cast<uint32_t>(SparseMode::RIGHT_DOWN_CAUSAL) ||
325	                sparseMode_ == static_cast<uint32_t>(SparseMode::BAND))) {
326	            sInnerSize_ = std::min(sInnerSize_, S_INNER_SIZE_1024); // attention mask压缩场景，基本块最大支持1024*1024
327	        }
328	
329	        // PA特性泛化场景，blockSize可能为112等值，无法被sInnerSize_整除，当step*base跨block时，搬运处理复杂，通过向下对齐避免
330	        if (blockSize_ != 0) {
331	            uint32_t blockSize = static_cast<uint32_t>(blockSize_);
332	            if ((sInnerSize_ > blockSize) && (sInnerSize_ % blockSize != 0)) {
333	                sInnerSize_ = (sInnerSize_ / blockSize) * blockSize;
334	            }
335	        }
336	        sInnerLoopTimes_ = (s2Size + sInnerSize_ - static_cast<uint32_t>(1)) / sInnerSize_;
337	        sInnerSizeTail_ = s2Size - (sInnerLoopTimes_ - static_cast<uint32_t>(1)) * sInnerSize_;
338	        // tiling下沉 && flash decoder场景时，sInnerSize_基块大小不按照真实值修改
339	        // 否则会导致 tiling下沉 && flash decoder 场景时开辟workspace空间大小小于真实运行时所需的workspace大小
340	        if (sInnerSize_ > s2Size) {
341	            sInnerSize_ = s2Size;
342	        }
343	    }
344	    sInnerSizeAlign_ = Align(sInnerSize_, BYTE_BLOCK); // 元素个数按照基本块大小对齐
345	    CalcMBaseSizeGqa();
346	}
347	
348	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcMBaseSizeGqa()
349	{
350	    if (inputLayout_ == "TND" || inputLayout_ == "NTD") {
351	        mBaseSize_ = M_BASE_SIZE_512;
352	        /*
353	         * BAND场景，带上sinkToken后，分块位置发生变化，从而导致计算band边界覆盖的基本块增加，导致无效计算量增大
354	         * 将基本块大小减小至256，减少无效计算量，缓解极端场景下分核劣势
355	        */
356	        if (sinkNum_ > 0 && sinkNum_ <= 256 && s1Size > S1_SIZE_16 &&
357	            sparseMode_ == static_cast<uint32_t>(SparseMode::BAND) &&
358	            nextToken == 0 && preToken % 512 >= sinkNum_) {
359	            // prefill阶段sparseMode4场景sinkToken耗时优化，当swa窗口比sinkNumber大时，会导致s2方向切块变多，计算量增加
360	            mBaseSize_ = M_BASE_SIZE_256;
361	        }
362	    } else {
363	        if (s1Size <= S1_SIZE_16) {
364	            if (sInnerSizeAlign_ <= S_INNER_SIZE_ALIGN_512) {
365	                mBaseSize_ = M_BASE_SIZE_512;
366	            } else if (sInnerSizeAlign_ <= S_INNER_SIZE_ALIGN_1024) {
367	                mBaseSize_ = M_BASE_SIZE_256;
368	            } else if (sInnerSizeAlign_ <= S_INNER_SIZE_ALIGN_2048) {
369	                mBaseSize_ = M_BASE_SIZE_128;
370	            } else if (sInnerSizeAlign_ <= S_INNER_SIZE_ALIGN_4096) {
371	                mBaseSize_ = M_BASE_SIZE_64;
372	            } else { // sInnerSizeAlign_最大值为8192
373	                mBaseSize_ = M_BASE_SIZE_32;
374	            }
375	        } else {
376	            mBaseSize_ = M_BASE_SIZE_512;
377	        }
378	    }
379	    
380	    softmaxWithBrcbFlag_ = (mBaseSize_ <= M_BASE_SIZE_128);
381	}
