383	void AiInfraFusedInferAttentionSinkMetadataKernel::CreateSplitInputGqa(BaseInfo &baseInfo, SplitParam &splitParam) const
384	{
385	    // 构造分核输入参数
386	    baseInfo.bSize = bSize;
387	    baseInfo.n2Size = n2Size;
388	    baseInfo.gSize = gSize;
389	    baseInfo.s2Size = s2Size;
390	    baseInfo.s1Size = s1Size;
391	    baseInfo.actualLenQDims = actualLenQDims;
392	    baseInfo.actualLenKvDims = actualLenKvDims;
393	    baseInfo.preToken = preToken;
394	    baseInfo.nextToken = nextToken;
395	    baseInfo.isS1G = inputLayout_ == "TND" || inputLayout_ == "BSH_BSND";
396	    baseInfo.sparseMode = sparseMode_;
397	    baseInfo.attenMaskFlag = attenMaskFlag;
398	    baseInfo.sinkNumber = sinkNum_;
399	    baseInfo.keySinkNumber = kSinkNum_;
400	    baseInfo.supportFD = (baseInfo.keySinkNumber == 0);  // sink做为独立tensor传入时,prefill不走FD
401	    baseInfo.batchInvariant = batchInvariant_;
402	    if (actualSeqLengths_ != nullptr) {
403	        baseInfo.isAccumSeqS1 = isAccumQSeq;
404	        baseInfo.actualSeqS1Size.reserve(bSize);
405	        const int64_t *s1Ptr = static_cast<const int64_t *>(actualSeqLengths_->GetData());
406	        for (uint32_t i = 0; i < bSize; ++i) {
407	            baseInfo.actualSeqS1Size.emplace_back(s1Ptr[i]);
408	        }
409	    }
410	    if (actualSeqLengthsKv_ != nullptr) {
411	        baseInfo.isAccumSeqS2 = isAccumKVSeq;
412	        const int64_t *s2Ptr = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
413	        for (uint32_t i = 0; i < bSize; ++i) {
414	            baseInfo.actualSeqS2Size.emplace_back(s2Ptr[i]);
415	        }
416	    }
417	
418	    splitParam.mBaseSize = mBaseSize_;
419	    splitParam.s2BaseSize = sInnerSize_;
420	    splitParam.gS1BaseSizeOfFd = mFdBaseSize_;
