462	bool AiInfraFusedInferAttentionSinkMetadataKernel::CheckSingleParam()
463	{
464	    // 1. 基础输出校验
465	    KERNEL_CHECK_NULLPTR(metaData_, false, "metadata is null");
466	    auto metaShape = metaData_->GetTensorShape();
467	    KERNEL_CHECK_NULLPTR(metaShape, false, "shape of metadata is null");
468	    KERNEL_CHECK_NULLPTR(metaData_->GetData(), false, "data of metadata is null");
469	    // 2. 核心数校验
470	    if (aicCoreNum_ == 0 || aivCoreNum_ == 0 || (aivCoreNum_ % aicCoreNum_ != 0)) {
471	        KERNEL_LOG_ERROR("Core num invalid: aic:%u, aiv:%u", aicCoreNum_, aivCoreNum_);
472	        return false;
473	    }
474	
475	    if (batchSize_ < 0) {
476	        KERNEL_LOG_ERROR("batchSize is %d, it should be greater than 0.", batchSize_);
477	        return false;
478	    }
479	
480	    constexpr int32_t BLOCK_SIZE_ALIGN_SIZE = 16;
481	    constexpr int32_t BLOCK_SIZE_MAX_SIZE = 1024;
482	    if (blockSize_ % BLOCK_SIZE_ALIGN_SIZE != 0) {
483	        KERNEL_LOG_ERROR("blockSize should aligned to 16, but got %d.", blockSize_);
484	        return false;
485	    }
486	    if (blockSize_ > BLOCK_SIZE_MAX_SIZE) {
487	        KERNEL_LOG_ERROR("blockSize should less equal than 1024, but got %d.", blockSize_);
488	        return false;
489	    }
490	
491	    if ((sparseMode_ != static_cast<uint32_t>(SparseMode::DEFAULT_MASK)) &&
492	        (sparseMode_ != static_cast<uint32_t>(SparseMode::ALL_MASK)) &&
493	        (sparseMode_ != static_cast<uint32_t>(SparseMode::LEFT_UP_CAUSAL)) &&
494	        (sparseMode_ != static_cast<uint32_t>(SparseMode::RIGHT_DOWN_CAUSAL)) &&
495	        (sparseMode_ != static_cast<uint32_t>(SparseMode::BAND))) {
496	        KERNEL_LOG_ERROR("sparseMode only supports 0/1/2/3/4, but got %u.", sparseMode_);
497	        return false;
498	    }
499	
500	    if (headDimQK_ <= 0) {
501	        KERNEL_LOG_ERROR("qk head num is %d, it should be greater than 0.", headDimQK_);
502	        return false;
503	    }
504	
505	    if (headDimV_ <= 0) {
506	        KERNEL_LOG_ERROR("value head num is %d, it should be greater than 0.", headDimV_);
507	        return false;
508	    }
509	
510	    return CheckSingleParaInputLayout();
511	}
