513	bool AiInfraFusedInferAttentionSinkMetadataKernel::CheckSingleParaInputLayout()
514	{
515	    const std::vector<std::string> inputLayoutList = {"BSH",
516	                                                      "BSND",
517	                                                      "BNSD",
518	                                                      "TND",
519	                                                      "NTD",
520	                                                      "BSH_NBSD",
521	                                                      "BSND_NBSD",
522	                                                      "BNSD_NBSD",
523	                                                      "TND_NTD",
524	                                                      "NTD_TND",
525	                                                      "BSH_BNSD",
526	                                                      "BSND_BNSD",
527	                                                      "BNSD_BSND"};
528	    if (std::find(inputLayoutList.begin(), inputLayoutList.end(), inputLayout_) == inputLayoutList.end()) {
529	        KERNEL_LOG_ERROR("input layout only supports BSH, BSND, BNSD, TND, NTD, BSH_NBSD, BSND_NBSD, BNSD_NBSD, "
530	                         "TND_NTD, NTD_TND, BSH_BNSD, BSND_BNSD, BNSD_BSND, but got %s.",
531	                         inputLayout_);
532	        return false;
533	    }
534	
535	    const std::vector<std::string> inputLayoutKvList = {
536	        "BSH", "BSND", "BNSD", "TND", "NTD", "NZ", "BnBsH", "BnNBsD", "PA"};
537	    if (std::find(inputLayoutKvList.begin(), inputLayoutKvList.end(), inputLayoutKv_) == inputLayoutKvList.end()) {
538	        KERNEL_LOG_ERROR("input layout only supports BSH, BSND, BNSD, TND, NTD, NZ, BnBsH, BnNBsD, PA, but got %s",
539	                         inputLayoutKv_);
540	        return false;
541	    }
542	
543	    if (inputLayout_ == "TND" || inputLayout_ == "NTD") {
544	        KERNEL_CHECK_NULLPTR(
545	            actualSeqLengths_, false, "When inputLayout is TND or NTD, actualSeqQLengths should not be null.");
546	        KERNEL_CHECK_NULLPTR(
547	            actualSeqLengthsKv_, false, "When inputLayout is TND or NTD, actualSeqKVLengths should not be null.");
548	    }
549	
550	    if (blockSize_ == 0) {
551	        if (inputLayoutKv_ != "BSH" && inputLayoutKv_ != "BSND" && inputLayoutKv_ != "BNSD" &&
552	            inputLayoutKv_ != "TND" && inputLayoutKv_ != "NTD") {
553	            KERNEL_LOG_ERROR("In BATCH_CONTINUOUS situation, key/value's layout only support BSH, BSND, BNSD, TND and "
554	                             "NTD in batch continuous scene, but got %s",
555	                             inputLayoutKv_);
556	            return false;
557	        }
558	        if (inputLayoutKv_ != inputLayout_) {
559	            KERNEL_LOG_ERROR("In BATCH_CONTINUOUS situation, key/value's layout and query's layout should be same in "
560	                             "batch continuous scene.");
561	            return false;
562	        }
563	    } else {
564	        if ((inputLayoutKv_ == "BnBsH" || inputLayoutKv_ == "BnNBsD" || inputLayoutKv_ == "NZ" ||
565	             inputLayoutKv_ == "PA") &&
566	            (inputLayout_ != "BSH" && inputLayout_ != "BSND" && inputLayout_ != "BNSD" && inputLayout_ != "TND" &&
567	             inputLayout_ != "NTD")) {
568	            KERNEL_LOG_ERROR("In PAGE_ATTENTION situation, query layout must be BSH, BSND, BNSD TND and TND in page "
569	                             "attention scene, but got %s",
570	                             inputLayout_);
571	            return false;
572	        }
573	    }
574	
575	    return true;
576	}
