620	bool AiInfraFusedInferAttentionSinkMetadataKernel::GetS1Size()
621	{
622	    // 获取S1基准值
623	    // 1、非TND/NTD时, 以max_seqlen_q为基准;
624	    // 2、TND/NTD时, actual_seq_lens_q必须传入, 以actual_seq_lens_q数组中的最大值为基准
625	    if (inputLayout_ == "TND" || inputLayout_ == "NTD") {
626	        const int64_t *actualSeqQ = static_cast<const int64_t *>(actualSeqLengths_->GetData());
627	        if (actualSeqQ == nullptr) {
628	            return false;
629	        }
630	
631	        uint32_t b = 0;
632	        if (!GetActualSeqLenSize(b)) {
633	            return false;
634	        }
635	        int64_t qActualSeqMax = 0;
636	        for (uint32_t i = 0; i < b; i++) {
637	            int64_t tmpS1 = (i == 0U) ? actualSeqQ[0] : (actualSeqQ[i] - actualSeqQ[i - 1U]);
638	            if (tmpS1 > qActualSeqMax) {
639	                qActualSeqMax = tmpS1;
640	            }
641	        }
642	        s1Size = static_cast<uint32_t>(qActualSeqMax);
643	    }
644	
645	    return true;
646	}
