670	bool AiInfraFusedInferAttentionSinkMetadataKernel::GetS2Size()
671	{
672	    // 获取S2基准值 连续或者tensorlist，都通过前缀和获取，其他取最大
673	    const int64_t *actualLenData = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
674	    if (actualLenData == nullptr) {
675	        return false;
676	    }
677	    uint32_t loop = std::min(static_cast<uint32_t>(actualSeqLengthsKv_->GetTensorShape()->GetDimSize(0)), bSize);
678	    if (inputLayoutKv_ == "TND" || inputLayoutKv_ == "NTD") {
679	        for (uint32_t i = 0; i < loop; i++) {
680	            int64_t tmpS = 0;
681	            tmpS = (i == 0U) ? actualLenData[0] : (actualLenData[i] - actualLenData[i - 1U]);
682	            s2Size = std::max(s2Size, tmpS);
683	        }
684	        if (kSinkNum_ > 0) {
685	            s2Size += kSinkNum_;
686	        }
687	        return true;
688	    } else {
689	        for (uint32_t i = 0; i < loop; i++) {
690	            s2Size = std::max(s2Size, actualLenData[i]);
691	        }
692	        if (kSinkNum_ > 0) {
693	            s2Size += kSinkNum_;
694	        }
695	        return true;
696	    }
697	
698	    return true;
699	}
