701	bool AiInfraFusedInferAttentionSinkMetadataKernel::GetPreNextToken()
702	{
703	    static int64_t SPARSE_MODE_INT_MAX = 2147483647;
704	    if (sparseMode_ == static_cast<uint32_t>(SparseMode::DEFAULT_MASK) && preTokens_ == SPARSE_MODE_INT_MAX &&
705	        nextTokens_ == SPARSE_MODE_INT_MAX) {
706	        attenMaskFlag = false;
707	    }
708	    if (sparseMode_ == static_cast<uint32_t>(SparseMode::ALL_MASK)) {
709	        preToken = SPARSE_MODE_INT_MAX;
710	        nextToken = SPARSE_MODE_INT_MAX;
711	    } else if (sparseMode_ == static_cast<uint32_t>(SparseMode::LEFT_UP_CAUSAL) ||
712	               sparseMode_ == static_cast<uint32_t>(SparseMode::RIGHT_DOWN_CAUSAL)) {
713	        nextToken = 0;
714	        preToken = SPARSE_MODE_INT_MAX;
715	    } else {
716	        preToken = preTokens_ == SPARSE_MODE_INT_MAX ? 0 : preTokens_;
717	        nextToken = nextTokens_ == SPARSE_MODE_INT_MAX ? 0 : nextTokens_;
718	    }
719	
720	    if (preToken > SPARSE_MODE_INT_MAX) {
721	        preToken = SPARSE_MODE_INT_MAX;
722	    } else if (preToken < -(SPARSE_MODE_INT_MAX)) {
723	        preToken = -(SPARSE_MODE_INT_MAX);
724	    }
725	    if (nextToken > SPARSE_MODE_INT_MAX) {
726	        nextToken = SPARSE_MODE_INT_MAX;
727	    } else if (nextToken < -(SPARSE_MODE_INT_MAX)) {
728	        nextToken = -(SPARSE_MODE_INT_MAX);
729	    }
730	
731	    if (preToken < 0 && nextToken < 0) {
732	        KERNEL_LOG_ERROR("preTokens(%ld) and nextTokens(%ld) cannot neither be negative number.", preToken, nextToken);
733	        return false;
734	    }
735	    if (nextToken * (-1) > preToken) {
736	        KERNEL_LOG_ERROR("nextToken line(%ld) should be higher than preToken line(%ld).", preToken, nextToken);
737	        return false;
738	    }
739	    return true;
740	}
