742	bool AiInfraFusedInferAttentionSinkMetadataKernel::GetActualSeqInfo()
743	{
744	    maxActualseq = s2Size;
745	    if (actualSeqLengthsKv_ != nullptr && actualSeqLengthsKv_->GetData() != nullptr) {
746	        const int64_t *actualLenData = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
747	        actualLenKvDims = actualSeqLengthsKv_->GetTensorShape()->GetDimSize(0);
748	        if (inputLayout_ == "TND" || inputLayout_ == "NTD") {
749	            isAccumQSeq = true;
750	        }
751	        uint32_t loop = ((actualLenKvDims == 1) && (kvListSeqLens.size() == 1)) ? 1 : bSize;
752	        loop = std::min(loop, actualLenKvDims);
753	        for (uint32_t i = 0; i < loop; i++) {
754	            int64_t actLen = actualLenData[i];
755	            needInit = (actLen == 0);
756	            maxActualseq = maxActualseq < actLen ? actLen : maxActualseq;
757	            if (actualLenData[i] != actualLenData[0]) {
758	                isSameActualseq = false;
759	                break;
760	            }
761	        }
762	    }
763	
764	    if (actualSeqLengths_ != nullptr && actualSeqLengths_->GetData() != nullptr) {
765	        const int64_t *actualLenQData = static_cast<const int64_t *>(actualSeqLengths_->GetData());
766	        actualLenQDims = actualSeqLengths_->GetTensorShape()->GetDimSize(0);
767	        if (inputLayoutKv_ == "TND" || inputLayoutKv_ == "NTD") {
768	            isAccumKVSeq = true;
769	        }
770	        uint32_t loop = std::min(bSize, actualLenQDims);
771	        for (uint32_t i = 0; i < loop; i++) {
772	            if (actualLenQData[i] != static_cast<int64_t>(s1Size)) {
773	                needInit = true;
774	                break;
775	            }
776	        }
777	    }
778	    return true;
779	}
