786	void AiInfraFusedInferAttentionSinkMetadataKernel::CheckIsMla()
787	{
788	    // 仅支持ROPE分开传输
789	    if (ropeHeadDim_ == 0U) {
790	        isMlaSink = false;
791	        return;
792	    }
793	
794	    // 仅支持Q&K&V的HeadDim为512, ROPE的HeadDim为64
795	    constexpr uint32_t QK_HEAD_DIM_512 = 512U;
796	    constexpr uint32_t ROPE_HEAD_DIM_64 = 64U;
797	    if ((headDimQK_ != headDimV_) || (headDimQK_ != QK_HEAD_DIM_512) || (ropeHeadDim_ != ROPE_HEAD_DIM_64)) {
798	        isMlaSink = false;
799	        return;
800	    }
801	
802	    // 仅支持KV_N为1
803	    if (n2Size != 1U) {
804	        isMlaSink = false;
805	        return;
806	    }
807	
808	    // 支持的input_layout范围
809	    const std::vector<std::string> layoutSupportList = {
810	        "BSH", "BSND", "BNSD", "TND", "BSH_NBSD", "BSND_NBSD", "BNSD_NBSD", "TND_NTD"};
811	    if (std::find(layoutSupportList.begin(), layoutSupportList.end(), inputLayout_) == layoutSupportList.end()) {
812	        isMlaSink = false;
813	        return;
814	    }
815	
816	    // 支持的sparse_mode值
817	    if ((sparseMode_ != static_cast<uint32_t>(SparseMode::DEFAULT_MASK)) &&
818	        (sparseMode_ != static_cast<uint32_t>(SparseMode::RIGHT_DOWN_CAUSAL)) &&
819	        (sparseMode_ != static_cast<uint32_t>(SparseMode::BAND))) {
820	        isMlaSink = false;
821	        return;
822	    }
823	
824	    // 支持的G的取值范围
825	    std::vector<uint32_t> gSizeSupportList = {1, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128};
826	    if (std::find(gSizeSupportList.begin(), gSizeSupportList.end(), gSize) == gSizeSupportList.end()) {
827	        isMlaSink = false;
828	        return;
829	    }
830	
831	    isMlaSink = true;
832	    return;
833	}
