858	
859	bool AiInfraFusedInferAttentionSinkMetadataKernel::CheckFeatureActualSeqLensQData()
860	{
861	    if (actualSeqLengths_ == nullptr) {
862	        qSize.push_back(s1Size);
863	        return true;
864	    }
865	
866	    const int64_t *actualSeq = static_cast<const int64_t *>(actualSeqLengths_->GetData());
867	    if (actualSeq == nullptr) {
868	        qSize.push_back(s1Size);
869	        return true;
870	    }
871	
872	    if (!GetActualSeqLenSize(actualSeqLengthsQSize_)) {
873	        return false;
874	    }
875	
876	    uint32_t loop = std::min(actualSeqLengthsQSize_, bSize);
877	    for (uint32_t i = 0; i < loop; i++) {
878	        int64_t tmpS1 = 0;
879	        if (inputLayout_ == "TND" || inputLayout_ == "NTD") {
880	            if (actualSeq[i] < 0) {
881	                KERNEL_LOG_ERROR("When q's Layout is TND or NTD, actualSeqQLengths[%u] should not be a negative "
882	                                 "number, but got %ld.",
883	                                 i,
884	                                 actualSeq[i]);
885	                return false;
886	            }
887	
888	            if (i > 0U && actualSeq[i] < actualSeq[i - 1U]) {
889	                KERNEL_LOG_ERROR("When q's Layout is TND or NTD, actualSeqQLengths[%u](%ld) should not be less than "
890	                                 "actualSeqQLengths[%u](%ld).",
891	                                 i,
892	                                 actualSeq[i],
893	                                 (i - 1U),
894	                                 actualSeq[i - 1U]);
895	                return false;
896	            }
897	
898	            tmpS1 = (i == 0U) ? actualSeq[0] : (actualSeq[i] - actualSeq[i - 1U]);
899	        } else {
900	            tmpS1 = actualSeq[i];
901	        }
902	        if (tmpS1 > static_cast<int64_t>(s1Size) || tmpS1 < 0) {
903	            KERNEL_LOG_ERROR(
904	                "actualSeqQLengths[%u] computed is %ld, it should be in range [0, Q_S(%u)].", i, tmpS1, s1Size);
905	            return false;
906	        }
907	        qSize.push_back(tmpS1);
908	    }
909	
910	    return true;
911	}
