974	bool AiInfraFusedInferAttentionSinkMetadataKernel::CheckParamSinkNumber()
975	{
976	    if (kSinkNum_ < 0) {
977	        KERNEL_LOG_ERROR("invalid Parameter kSinkNum");
978	        return false;
979	    }
980	    
981	    if (kSinkNum_ == 0) {
982	        return true;
983	    }
984	
985	    if (sinkNum_ > 0) {
986	        KERNEL_LOG_ERROR("Conflict paramSink and learnable attribute cannot coexist");
987	        return false;
988	    }
989	
990	    if (sparseMode_ != static_cast<uint32_t>(SparseMode::BAND)) {
991	        KERNEL_LOG_ERROR("paramSink only support sparseMode=4(SWA), but got %u", sparseMode_);
992	        return false;
993	    }
994	
995	    if (inputLayout_ != "TND") {
996	        KERNEL_LOG_ERROR("query layout must be TND, but query layout is %s", inputLayout_.c_str());
997	        return false;
998	    }
999	
1000	    if ((actualSeqLengths_ == nullptr) || (actualSeqLengths_->GetData() == nullptr) ||
1001	        (actualSeqLengthsKv_ == nullptr) || (actualSeqLengthsKv_->GetData() == nullptr)) {
1002	        KERNEL_LOG_ERROR("actualSeqLengths_ or actualSeqLengthsKv_ cannot be empty.");
1003	        return false;
1004	    }
1005	
1006	    const int64_t *actualSeqLensDataQ = static_cast<const int64_t *>(actualSeqLengths_->GetData());
1007	    const int64_t *actualSeqLensData = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
1008	    int64_t tmpS2Size = 0;
1009	    for (uint32_t i = 0; i < actualSeqLengthsQSize_; i++) {
1010	        int64_t tmpS1Size = (i == 0U) ? actualSeqLensDataQ[0] : (actualSeqLensDataQ[i] - actualSeqLensDataQ[i - 1U]);
1011	        if (blockSize_ != 0) {
1012	            tmpS2Size = actualSeqLensData[i];
1013	        } else {
1014	            tmpS2Size = (i == 0U) ? actualSeqLensData[0] : (actualSeqLensData[i] - actualSeqLensData[i - 1U]);
1015	        }
1016	        if (tmpS2Size == 0) {
1017	            // 当s2=0时，为T轴padding场景，此时不需要校验行无效
1018	            continue;
1019	        }
1020	        // 不支持行无效
1021	        if (preToken < 0 || (nextToken < (tmpS1Size - tmpS2Size))) {
1022	            KERNEL_LOG_ERROR("preToken < 0 or nextToken < (s1 - s2) is not supported when sink tensor exists");
1023	            return false;
1024	        }
1025	    }
1026	
1027	    return true;
1028	}
