1030	bool AiInfraFusedInferAttentionSinkMetadataKernel::CheckSinkNumber()
1031	{
1032	    int64_t maxSinkNumber = 512;
1033	
1034	    if (sinkNum_ == 0) {
1035	        return true;
1036	    }
1037	
1038	    // sinkNum不能为奇数
1039	    if (sinkNum_ < 0 || sinkNum_ > maxSinkNumber || sinkNum_ % 2 == 1) {
1040	        KERNEL_LOG_ERROR("invalid Parameter sinkNumber");
1041	        return false;
1042	    }
1043	
1044	    if (sinkNum_ > 0 && inputLayout_ != "TND") {
1045	        KERNEL_LOG_ERROR("when sinkNumber > 0, qLayout should TND");
1046	        return false;
1047	    }
1048	
1049	    uint64_t minActualKvSeqLen = 1000000000000;
1050	    const int64_t *actualKvLenData = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
1051	    if (actualKvLenData != nullptr) {
1052	        uint32_t loop = actualSeqLengthsKv_->GetTensorShape()->GetDimSize(0);
1053	        for (uint32_t i = 0; i < loop; i++) {
1054	            int64_t tmpS = 0;
1055	            if (blockSize_ != 0) {
1056	                tmpS = actualKvLenData[i];
1057	            } else {
1058	                tmpS = (i == 0U) ? actualKvLenData[0] : (actualKvLenData[i] - actualKvLenData[i - 1U]);
1059	            }
1060	            minActualKvSeqLen = minActualKvSeqLen < tmpS ? minActualKvSeqLen : tmpS;
1061	        }
1062	    }
1063	
1064	    if (minActualKvSeqLen < sinkNum_) {
1065	        KERNEL_LOG_ERROR("when sinkNumber > 0, and qLayout is TND, sinknumber(%ld) should <= minActualKvSeqLen(%ld)",
1066	                         sinkNum_,
1067	                         minActualKvSeqLen);
1068	        return false;
1069	    }
1070	
1071	    return CheckMlaSinkNumber();
1072	}
