1074	bool AiInfraFusedInferAttentionSinkMetadataKernel::CheckMlaSinkNumber()
1075	{
1076	    // D=128时，走GQA模板
1077	    if (ropeHeadDim_ == 0U || headDimV_ != 512U) {
1078	        return true;
1079	    }
1080	    if (sparseMode_ != static_cast<uint32_t>(SparseMode::BAND)) {
1081	        KERNEL_LOG_ERROR("sparseMode only support 4 when sinkNumber(%ld) exist and D is 512", sinkNum_);
1082	        return false;
1083	    }
1084	    // MLA sink 支持 TND、TND_NTD layout，继承GQA的校验
1085	
1086	    const int64_t *actualSeqLensDataQ = static_cast<const int64_t *>(actualSeqLengths_->GetData());
1087	    const int64_t *actualSeqLensData = static_cast<const int64_t *>(actualSeqLengthsKv_->GetData());
1088	    int64_t tmpS2Size = 0;
1089	    for (uint32_t i = 0; i < actualSeqLengthsQSize_; i++) {
1090	        int64_t tmpS1Size = (i == 0U) ? actualSeqLensDataQ[0] : (actualSeqLensDataQ[i] - actualSeqLensDataQ[i - 1U]);
1091	        if (blockSize_ != 0) {
1092	            tmpS2Size = actualSeqLensData[i];
1093	        } else {
1094	            tmpS2Size = (i == 0U) ? actualSeqLensData[0] : (actualSeqLensData[i] - actualSeqLensData[i - 1U]);
1095	        }
1096	        if (tmpS2Size == sinkNum_) {
1097	            // 当s2=sinkNumber时，为T轴padding场景，此时不需要校验行无效
1098	            continue;
1099	        }
1100	        // 不支持行无效
1101	        if (preToken < 0 || (nextToken < (tmpS1Size - tmpS2Size + sinkNum_))) {
1102	            KERNEL_LOG_ERROR("preToken < 0 or nextToken < (s1 - s2 + sinkNumber) is not supported "
1103	                             "when sinkNumber(%ld) exist and D is 512",
1104	                             sinkNum_);
1105	            return false;
1106	        }
1107	    }
1108	    return true;
1109	}
