1210	int64_t AiInfraFusedInferAttentionSinkMetadataKernel::CalcPreTokenLeftUp(uint32_t s1Size,
1211	                                                                         uint32_t s2Size,
1212	                                                                         const BaseInfo &baseInfo)
1213	{
1214	    auto mode = static_cast<SparseMode>(baseInfo.sparseMode);
1215	    if (mode == SparseMode::BAND) {
