1221	int64_t AiInfraFusedInferAttentionSinkMetadataKernel::CalcNextTokenLeftUp(uint32_t s1Size,
1222	                                                                          uint32_t s2Size,
1223	                                                                          const BaseInfo &baseInfo)
1224	{
1225	    auto mode = static_cast<SparseMode>(baseInfo.sparseMode);
1226	    switch (mode) {
1227	        case SparseMode::DEFAULT_MASK:
1228	        case SparseMode::ALL_MASK:
1229	        case SparseMode::LEFT_UP_CAUSAL:
1230	            return baseInfo.nextToken;
1231	        case SparseMode::RIGHT_DOWN_CAUSAL:
1232	            return static_cast<int64_t>(s2Size) - static_cast<int64_t>(s1Size);
1233	        case SparseMode::BAND:
1234	            return static_cast<int64_t>(s2Size) - static_cast<int64_t>(s1Size) + baseInfo.nextToken;
1235	        default:
1236	            return baseInfo.nextToken;
1237	    }
1238	}
