1240	int64_t AiInfraFusedInferAttentionSinkMetadataKernel::CalcCost(uint32_t basicM, uint32_t basicS2)
1241	{
1242	    uint32_t alignCoefM = 16U;
1243	    uint32_t alignCoefS2 = 64U;
1244	    uint32_t alignBasicM = (basicM + alignCoefM - 1U) >> 4U; // 按alignCoefM对齐，向上取整，4：移位操作实现除16
1245	    uint32_t alignBasicS2 = (basicS2 + alignCoefS2 - 1U) >> 6U; // 按alignCoefS2对齐，向上取整，6：移位操作实现除64
1246	    return static_cast<int64_t>(6U * alignBasicM + 10U * alignBasicS2); // 6：M轴系数，10：S2轴系数
1247	}
1248	
1249	BlockCost<int64_t> AiInfraFusedInferAttentionSinkMetadataKernel::CalcCostTable(uint32_t s1NormalSize,
1250	                                                                               uint32_t s2NormalSize,
1251	                                                                               uint32_t s1GTailSize,
1252	                                                                               uint32_t s2TailSize)
1253	{
1254	    BlockCost<int64_t> typeCost{};
1255	    typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)][static_cast<size_t>(BlockType::NORMAL_BLOCK)] =
1256	        CalcCost(s1NormalSize, s2NormalSize);
1257	    typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)][static_cast<size_t>(BlockType::NORMAL_BLOCK)] =
1258	        (s1GTailSize == 0U) ? 0U : CalcCost(s1GTailSize, s2NormalSize);
1259	    typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)][static_cast<size_t>(BlockType::TAIL_BLOCK)] =
1260	        (s2TailSize == 0U) ? 0U : CalcCost(s1NormalSize, s2TailSize);
1261	    typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)][static_cast<size_t>(BlockType::TAIL_BLOCK)] =
1262	        (s1GTailSize == 0U || s2TailSize == 0U) ? 0U : CalcCost(s1GTailSize, s2TailSize);
1263	    return typeCost;
1264	}
1265	
1266	Range<uint32_t> AiInfraFusedInferAttentionSinkMetadataKernel::CalcS2Range(uint32_t s1GIdx,
1267	                                                                          const BaseInfo &baseInfo,
1268	                                                                          const SplitParam &splitParam,
1269	                                                                          const BatchCache &batchCache)
1270	{
1271	    uint32_t s2Start = 0U;
1272	    uint32_t s2End = 0U;
1273	
1274	    // actual seq == 0
1275	    if (batchCache.s1Size == 0U || batchCache.s2Size == 0U) {
1276	        return std::make_pair(s2Start, s2End);
1277	    }
1278	
1279	    // no mask
1280	    if (!baseInfo.attenMaskFlag) {
1281	        s2Start = 0U;
1282	        s2End = (batchCache.s2Size + splitParam.s2BaseSize - 1U) / splitParam.s2BaseSize;
1283	        return std::make_pair(s2Start, s2End);
1284	    }
1285	
1286	    // 1. calc index of s2FirstToken, s2LastToken by index of s1GFirstToken, s1GLastToken
1287	    int64_t s1GFirstToken = static_cast<int64_t>(s1GIdx) * static_cast<int64_t>(splitParam.mBaseSize);
1288	    int64_t s1GLastToken = std::min(s1GFirstToken + static_cast<int64_t>(splitParam.mBaseSize),
1289	                                    static_cast<int64_t>(batchCache.s1Size) * static_cast<int64_t>(baseInfo.gSize)) -
1290	                           1;
1291	
1292	    int64_t s1FirstToken = 0;
1293	    int64_t s1LastToken = 0;
1294	    if (baseInfo.isS1G) {
1295	        s1FirstToken = s1GFirstToken / static_cast<int64_t>(baseInfo.gSize);
1296	        s1LastToken = s1GLastToken / static_cast<int64_t>(baseInfo.gSize);
1297	    } else {
1298	        if (s1GFirstToken / batchCache.s1Size == s1GLastToken / batchCache.s1Size) {
1299	            // start and end locate in one G
1300	            s1FirstToken = s1GFirstToken % static_cast<int64_t>(batchCache.s1Size);
1301	            s1LastToken = s1GLastToken % static_cast<int64_t>(batchCache.s1Size);
1302	        } else {
1303	            // start and end locate in tow or more G, but working same as crossing a complete block
1304	            s1FirstToken = 0;
1305	            s1LastToken = batchCache.s1Size;
1306	        }
1307	    }
1308	
1309	    int64_t s2FirstToken = s1FirstToken - batchCache.preTokenLeftUp;
1310	    int64_t s2LastToken = s1LastToken + batchCache.nextTokenLeftUp;
1311	
1312	    // 2. trans index of token to index of block
1313	    // no valid token
1314	    if (s2FirstToken >= batchCache.s2Size || s2LastToken < 0 || s2LastToken < s2FirstToken) {
1315	        s2Start = 0U;
1316	        s2End = 0U;
1317	        return std::make_pair(s2Start, s2End);
1318	    }
1319	
1320	    // get valid range
1321	    s2FirstToken = Clip(s2FirstToken, static_cast<int64_t>(0), static_cast<int64_t>(batchCache.s2Size - 1U));
1322	    s2LastToken = Clip(s2LastToken, static_cast<int64_t>(0), static_cast<int64_t>(batchCache.s2Size - 1U));
1323	    s2Start = static_cast<uint32_t>(s2FirstToken) / splitParam.s2BaseSize;
1324	    s2End = static_cast<uint32_t>(s2LastToken) / splitParam.s2BaseSize +
1325	            1U; // end of block index, +1 for Right-open interval
1326	    return std::make_pair(s2Start, s2End);
1327	}
1328	
1329	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcSplitInfo(SplitContext &splitContext)
1330	{
1331	    const BaseInfo &baseInfo = splitContext.baseInfo;
1332	    const SplitParam &splitParam = splitContext.splitParam;
1333	    uint32_t s2Size;
1334	    // 计算每个batch的切分，统计是否为空batch，记录最后有效batch（每个batch的每个N2切分是一样的）
1335	    SplitInfo &splitInfo = splitContext.splitInfo;
1336	    for (uint32_t bIdx = 0; bIdx < baseInfo.bSize; bIdx++) {
1337	        uint32_t s1Size = GetS1SeqSize(bIdx, baseInfo);
1338	        if (baseInfo.keySinkNumber && baseInfo.supportFD) {
1339	            s2Size = baseInfo.keySinkNumber + GetS2SeqSize(bIdx, baseInfo);
1340	        } else {
1341	            s2Size = GetS2SeqSize(bIdx, baseInfo);
1342	        }
1343	
1344	        splitInfo.s1GBaseNum[bIdx] = (s1Size * baseInfo.gSize + (splitParam.mBaseSize - 1U)) / splitParam.mBaseSize;
1345	        splitInfo.s1GTailSize[bIdx] = (s1Size * baseInfo.gSize) % splitParam.mBaseSize;
1346	        splitInfo.s2BaseNum[bIdx] = (s2Size + splitParam.s2BaseSize - 1U) / splitParam.s2BaseSize;
1347	        splitInfo.s2TailSize[bIdx] = s2Size % splitParam.s2BaseSize;
1348	        if (splitInfo.s1GBaseNum[bIdx] != 0U && splitInfo.s2BaseNum[bIdx] != 0U) {
1349	            splitInfo.isKvSeqAllZero = false;
1350	        }
1351	    }
1352	}
1353	
1354	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcBatchCache(uint32_t bIdx,
1355	                                                                  const SplitContext &splitContext,
1356	                                                                  BatchCache &batchCache)
1357	{
1358	    const BaseInfo &baseInfo = splitContext.baseInfo;
1359	    const SplitParam &splitParam = splitContext.splitParam;
1360	    const SplitInfo &splitInfo = splitContext.splitInfo;
1361	
1362	    batchCache.bIdx = bIdx;
1363	    batchCache.s1Size = GetS1SeqSize(bIdx, baseInfo);
1364	    if (baseInfo.keySinkNumber && baseInfo.supportFD) {
1365	        batchCache.s2Size = GetS2SeqSize(bIdx, baseInfo) + baseInfo.keySinkNumber;
1366	    } else {
1367	        batchCache.s2Size = GetS2SeqSize(bIdx, baseInfo);
1368	    }
1369	
1370	    batchCache.preTokenLeftUp = CalcPreTokenLeftUp(batchCache.s1Size, batchCache.s2Size, baseInfo);
1371	    batchCache.nextTokenLeftUp = CalcNextTokenLeftUp(batchCache.s1Size, batchCache.s2Size, baseInfo);
1372	    batchCache.typeCost = CalcCostTable(
1373	        splitParam.mBaseSize, splitParam.s2BaseSize, splitInfo.s1GTailSize[bIdx], splitInfo.s2TailSize[bIdx]);
1374	}
