1376	// AiInfraFusedInferAttentionSink自定义算子新增函数：计算s1GIdx行sink块的Cost和块数
1377	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcS1GCacheWithSinkNumber(uint32_t s1GIdx,
1378	                                                                              const SplitContext &splitContext,
1379	                                                                              const BatchCache &batchCache,
1380	                                                                              S1GCache &s1GCache,
1381	                                                                              uint32_t sinkNumber)
1382	{
1383	    s1GCache.s2Start = 0;
1384	    if (s1GCache.s2End == 0) {
1385	        return;
1386	    }
1387	    if (s1GCache.firstTokenWithSinkNumber == 0) {
1388	        return;
1389	    }
1390	    const BaseInfo &baseInfo = splitContext.baseInfo;
1391	    const SplitParam &splitParam = splitContext.splitParam;
1392	    const SplitInfo &splitInfo = splitContext.splitInfo;
1393	    uint32_t sinkBlockLastIndex =
1394	        (static_cast<uint32_t>(sinkNumber) + splitParam.s2BaseSize - 1) / splitParam.s2BaseSize - 1;
1395	    if (s1GCache.firstTokenWithSinkNumber > sinkBlockLastIndex) {
1396	        s1GCache.s1GBlock += sinkBlockLastIndex + 1;
1397	        if (s1GIdx == (splitInfo.s1GBaseNum[batchCache.bIdx] - 1U) && splitInfo.s1GTailSize[batchCache.bIdx] != 0U) {
1398	            s1GCache.s1GCost += batchCache.typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)]
1399	                                                   [static_cast<size_t>(BlockType::NORMAL_BLOCK)] *
1400	                                (sinkBlockLastIndex + 1);
1401	        } else {
1402	            s1GCache.s1GCost += batchCache.typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)]
1403	                                                   [static_cast<size_t>(BlockType::NORMAL_BLOCK)] *
1404	                                (sinkBlockLastIndex + 1);
1405	        }
1406	    } else {
1407	        s1GCache.s1GBlock += s1GCache.firstTokenWithSinkNumber;
1408	        if (s1GIdx == (splitInfo.s1GBaseNum[batchCache.bIdx] - 1U) && splitInfo.s1GTailSize[batchCache.bIdx] != 0U) {
1409	            s1GCache.s1GCost += batchCache.typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)]
1410	                                                   [static_cast<size_t>(BlockType::NORMAL_BLOCK)] *
1411	                                s1GCache.firstTokenWithSinkNumber;
1412	        } else {
1413	            s1GCache.s1GCost += batchCache.typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)]
1414	                                                   [static_cast<size_t>(BlockType::NORMAL_BLOCK)] *
1415	                                s1GCache.firstTokenWithSinkNumber;
1416	        }
1417	    }
1418	}
