1420	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcS1GCache(uint32_t s1GIdx,
1421	                                                                const SplitContext &splitContext,
1422	                                                                const BatchCache &batchCache,
1423	                                                                S1GCache &s1GCache)
1424	{
1425	    const BaseInfo &baseInfo = splitContext.baseInfo;
1426	    const SplitParam &splitParam = splitContext.splitParam;
1427	    const SplitInfo &splitInfo = splitContext.splitInfo;
1428	
1429	    s1GCache.bIdx = batchCache.bIdx;
1430	    s1GCache.s1GIdx = s1GIdx;
1431	
1432	    auto s2Range = CalcS2Range(s1GIdx, baseInfo, splitParam, batchCache);
1433	    s1GCache.s2Start = s2Range.first;
1434	    s1GCache.s2End = s2Range.second;
1435	    s1GCache.firstTokenWithSinkNumber =
1436	        s2Range
1437	            .first; // AiInfraFusedInferAttentionSink自定义算子新增参数：表达sinkNumber>0时，s1GIdx行preToken所在的第一个块的下标
1438	    if (s1GCache.s2Start >= s1GCache.s2End) {
1439	        s1GCache.s1GBlock = 0;
1440	        s1GCache.s1GCost = 0;
1441	        s1GCache.s1GLastBlockCost = 0;
1442	        s1GCache.s1GNormalBlockCost = 0;
1443	        return;
1444	    }
1445	
1446	    // 计算S2方向满块、尾块数量
1447	    s1GCache.s1GBlock = s1GCache.s2End - s1GCache.s2Start;
1448	    uint32_t curTailS2Num =
1449	        (splitInfo.s2TailSize[batchCache.bIdx] != 0U && s1GCache.s2End == splitInfo.s2BaseNum[batchCache.bIdx]) ? 1U
1450	                                                                                                                : 0U;
1451	    uint32_t curNormalS2Num = s1GCache.s1GBlock - curTailS2Num;
1452	    if (splitInfo.s1GBaseNum[batchCache.bIdx] == 0) {
1453	        s1GCache.s1GCost = 0;
1454	        s1GCache.s1GLastBlockCost = 0;
1455	        s1GCache.s1GNormalBlockCost = 0;
1456	    } else if (s1GIdx == (splitInfo.s1GBaseNum[batchCache.bIdx] - 1U) && splitInfo.s1GTailSize[batchCache.bIdx] != 0U) {
1457	        s1GCache.s1GCost =
1458	            batchCache.typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)]
1459	                               [static_cast<size_t>(BlockType::NORMAL_BLOCK)] *
1460	                curNormalS2Num +
1461	            batchCache
1462	                    .typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)][static_cast<size_t>(BlockType::TAIL_BLOCK)] *
1463	                curTailS2Num;
1464	        s1GCache.s1GLastBlockCost =
1465	            curTailS2Num > 0U
1466	                ? batchCache
1467	                      .typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)][static_cast<size_t>(BlockType::TAIL_BLOCK)]
1468	                : batchCache.typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)]
1469	                                     [static_cast<size_t>(BlockType::NORMAL_BLOCK)];
1470	        s1GCache.s1GNormalBlockCost =
1471	            batchCache
1472	                .typeCost[static_cast<size_t>(BlockType::TAIL_BLOCK)][static_cast<size_t>(BlockType::NORMAL_BLOCK)];
1473	    } else {
1474	        s1GCache.s1GCost = batchCache.typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)]
1475	                                              [static_cast<size_t>(BlockType::NORMAL_BLOCK)] *
1476	                               curNormalS2Num +
1477	                           batchCache.typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)]
1478	                                              [static_cast<size_t>(BlockType::TAIL_BLOCK)] *
1479	                               curTailS2Num;
1480	        s1GCache.s1GLastBlockCost = curTailS2Num > 0U
1481	                                        ? batchCache.typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)]
1482	                                                             [static_cast<size_t>(BlockType::TAIL_BLOCK)]
1483	                                        : batchCache.typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)]
1484	                                                             [static_cast<size_t>(BlockType::NORMAL_BLOCK)];
1485	        s1GCache.s1GNormalBlockCost =
1486	            batchCache
1487	                .typeCost[static_cast<size_t>(BlockType::NORMAL_BLOCK)][static_cast<size_t>(BlockType::NORMAL_BLOCK)];
1488	    }
1489	    uint32_t sinkNumber = (baseInfo.keySinkNumber && baseInfo.supportFD) ? baseInfo.keySinkNumber : baseInfo.sinkNumber;
1490	    if (sinkNumber > 0 &&
1491	        baseInfo.sparseMode == 4U) { // AiInfraFusedInferAttentionSink自定义算子新增部分：计算s1GIdx行sink块的Cost和块数
1492	        CalcS1GCacheWithSinkNumber(s1GIdx, splitContext, batchCache, s1GCache, sinkNumber);
1493	    }
1494	}
