1540	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcBatchCost(uint32_t bIdx,
1541	                                                                 const SplitContext &splitContext,
1542	                                                                 CostInfo &costInfo)
1543	{
1544	    const BaseInfo &baseInfo = splitContext.baseInfo;
1545	    const SplitInfo &splitInfo = splitContext.splitInfo;
1546	
1547	    costInfo.bN2CostOfEachBatch[bIdx] = 0;
1548	    costInfo.bN2BlockOfEachBatch[bIdx] = 0U;
1549	    costInfo.bN2LastBlockCostOfEachBatch[bIdx] = 0U;
1550	
1551	    if (GetS1SeqSize(bIdx, baseInfo) == 0U || GetS2SeqSize(bIdx, baseInfo) == 0U) {
1552	        return;
1553	    }
1554	
1555	    BatchCache bCache;
1556	    S1GCache s1GCache;
1557	    CalcBatchCache(bIdx, splitContext, bCache);
1558	    for (uint32_t s1GIdx = 0; s1GIdx < splitInfo.s1GBaseNum[bIdx]; s1GIdx++) {
1559	        CalcS1GCache(s1GIdx, splitContext, bCache, s1GCache);
1560	        costInfo.bN2CostOfEachBatch[bIdx] += s1GCache.s1GCost;
1561	        costInfo.bN2BlockOfEachBatch[bIdx] += s1GCache.s1GBlock;
1562	
1563	        if (s1GCache.s1GBlock > 0) {
1564	            costInfo.bN2LastBlockCostOfEachBatch[bIdx] = s1GCache.s1GLastBlockCost;
1565	        }
1566	    }
1567	}
