1569	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcCostInfo(SplitContext &splitContext)
1570	{
1571	    const BaseInfo &baseInfo = splitContext.baseInfo;
1572	    const SplitInfo &splitInfo = splitContext.splitInfo;
1573	
1574	    CostInfo &costInfo = splitContext.costInfo;
1575	
1576	    if (splitInfo.isKvSeqAllZero) {
1577	        costInfo.totalCost = 0;
1578	        costInfo.totalBlockNum = 0U;
1579	        return;
1580	    }
1581	
1582	    // 计算batch的负载并记录，用于按batch分配，需要按行计算起止点，统计块数、负载
1583	    for (uint32_t bIdx = 0; bIdx < baseInfo.bSize; bIdx++) {
1584	        CalcBatchCost(bIdx, splitContext, costInfo);
1585	        costInfo.totalCost += costInfo.bN2CostOfEachBatch[bIdx] * baseInfo.n2Size;
1586	        costInfo.totalBlockNum += costInfo.bN2BlockOfEachBatch[bIdx] * baseInfo.n2Size;
1587	    }
1588	}
