1590	void AiInfraFusedInferAttentionSinkMetadataKernel::UpdateCursor(const SplitContext &splitContext,
1591	                                                                AssignContext &assignContext)
1592	{
1593	    const BaseInfo &baseInfo = splitContext.baseInfo;
1594	    const SplitInfo &splitInfo = splitContext.splitInfo;
1595	    const CostInfo &costInfo = splitContext.costInfo;
1596	
1597	    bool upDataS1G = false;
1598	    bool upDateBatch = false;
1599	
1600	    // Update S2
1601	    if (assignContext.curS2Idx >= assignContext.s1GCache.s2End) { // 边界assignInfo.s2End是取不到的开区间
1602	        assignContext.curS2Idx = 0U;
1603	        assignContext.curS1GIdx++;
1604	        upDataS1G = true;
1605	    }
1606	
1607	    // Update S1G
1608	    if (assignContext.curS1GIdx >= splitInfo.s1GBaseNum[assignContext.curBIdx]) {
1609	        assignContext.curS1GIdx = 0U;
1610	        assignContext.curBN2Idx++;
1611	    }
1612	
1613	    // Update Batch
1614	    if (assignContext.curBN2Idx ==
1615	        baseInfo.bSize * baseInfo.n2Size) { // 所有负载全部分配完，设置最后一个核的右开区间，返回
1616	        assignContext.curS1GIdx = 0U;
1617	        assignContext.curS2Idx = 0U;
1618	        assignContext.isFinished = true;
1619	        return;
1620	    }
1621	
1622	    if (assignContext.curBN2Idx / baseInfo.n2Size != assignContext.curBIdx) {
1623	        assignContext.curBIdx = assignContext.curBN2Idx / baseInfo.n2Size;
1624	        assignContext.curS1GIdx = 0U;
1625	        upDateBatch = true;
1626	        upDataS1G = true;
1627	    }
1628	
1629	    // Update Cache
1630	    if (upDateBatch) {
1631	        CalcBatchCache(assignContext.curBIdx, splitContext, assignContext.batchCache);
1632	        assignContext.bN2Cost = costInfo.bN2CostOfEachBatch[assignContext.curBIdx];
1633	        assignContext.bN2Block = costInfo.bN2BlockOfEachBatch[assignContext.curBIdx];
1634	    }
1635	    if (upDataS1G) {
1636	        CalcS1GCache(assignContext.curS1GIdx, splitContext, assignContext.batchCache, assignContext.s1GCache);
1637	        assignContext.curS2Idx = assignContext.s1GCache.s2Start;
1638	    }
1639	}
