1641	void AiInfraFusedInferAttentionSinkMetadataKernel::AssignByBatch(const SplitContext &splitContext,
1642	                                                                 AssignContext &assignContext)
1643	{
1644	    if (assignContext.isFinished) {
1645	        return;
1646	    }
1647	
1648	    const BaseInfo &baseInfo = splitContext.baseInfo;
1649	    const CostInfo &costInfo = splitContext.costInfo;
1650	
1651	    while (assignContext.bN2Cost == 0 ||
1652	           IsWithinTolerance(assignContext.coreCache.costLimit,
1653	                             costInfo.bN2LastBlockCostOfEachBatch[assignContext.curBIdx] / FA_TOLERANCE_RATIO,
1654	                             assignContext.coreCache.cost + assignContext.bN2Cost)) {
1655	        assignContext.coreCache.cost += assignContext.bN2Cost;
1656	        assignContext.coreCache.block += assignContext.bN2Block;
1657	        assignContext.curBN2Idx++;
1658	
1659	        // to the end
1660	        if (assignContext.curBN2Idx == baseInfo.bSize * baseInfo.n2Size) {
1661	            assignContext.curS1GIdx = 0U;
1662	            assignContext.curS2Idx = 0U;
1663	            assignContext.isFinished = true;
1664	            return;
1665	        }
1666	
1667	        // next batch
1668	        if (assignContext.curBN2Idx / baseInfo.n2Size != assignContext.curBIdx) {
1669	            assignContext.curBIdx = assignContext.curBN2Idx / baseInfo.n2Size;
1670	            CalcBatchCache(assignContext.curBIdx, splitContext, assignContext.batchCache);
1671	        }
1672	
1673	        assignContext.bN2Cost = costInfo.bN2CostOfEachBatch[assignContext.curBIdx];
1674	        assignContext.bN2Block = costInfo.bN2BlockOfEachBatch[assignContext.curBIdx];
1675	        assignContext.curS1GIdx = 0U;
1676	        CalcS1GCache(assignContext.curS1GIdx, splitContext, assignContext.batchCache, assignContext.s1GCache);
1677	        assignContext.curS2Idx = assignContext.s1GCache.s2Start;
1678	    }
1679	}
