1681	void AiInfraFusedInferAttentionSinkMetadataKernel::AssignByRow(const SplitContext &splitContext,
1682	                                                               AssignContext &assignContext)
1683	{
1684	    if (assignContext.isFinished) {
1685	        return;
1686	    }
1687	
1688	    while (IsWithinTolerance(assignContext.coreCache.costLimit,
1689	                             assignContext.s1GCache.s1GLastBlockCost / FA_TOLERANCE_RATIO,
1690	                             assignContext.coreCache.cost + assignContext.s1GCache.s1GCost)) {
1691	        assignContext.coreCache.cost += assignContext.s1GCache.s1GCost;
1692	        assignContext.coreCache.block += assignContext.s1GCache.s1GBlock;
1693	
1694	        // 当前batch被分配一行出去，更新剩余负载
1695	        assignContext.bN2Cost = assignContext.bN2Cost > assignContext.s1GCache.s1GCost
1696	                                    ? assignContext.bN2Cost - assignContext.s1GCache.s1GCost
1697	                                    : 0;
1698	        assignContext.bN2Block = assignContext.bN2Block > assignContext.s1GCache.s1GBlock
1699	                                     ? assignContext.bN2Block - assignContext.s1GCache.s1GBlock
1700	                                     : 0U;
1701	        // 计算新一行的信息
1702	        assignContext.curS1GIdx++;
1703	        CalcS1GCache(assignContext.curS1GIdx, splitContext, assignContext.batchCache, assignContext.s1GCache);
1704	        while (assignContext.s1GCache.s1GBlock == 0) {
1705	            assignContext.curS1GIdx++;
1706	            CalcS1GCache(assignContext.curS1GIdx, splitContext, assignContext.batchCache, assignContext.s1GCache);
1707	        }
1708	        assignContext.curS2Idx = assignContext.s1GCache.s2Start;
1709	    }
1710	}
