1712	// AiInfraFusedInferAttentionSink自定义算子新增函数：按block块分配时，分配完之后需要更新curS2Idx,需要跳过sink和preToken之间被掩掉的块
1713	void AiInfraFusedInferAttentionSinkMetadataKernel::UpdateCurS2IdxWithSinkNumber(const SplitContext &splitContext,
1714	                                                                                AssignContext &assignContext,
1715	                                                                                uint32_t sinkNumber)
1716	{
1717	    const BaseInfo &baseInfo = splitContext.baseInfo;
1718	    const SplitParam &splitParam = splitContext.splitParam;
1719	    if (assignContext.s1GCache.s2End == 0) {
1720	        return;
1721	    }
1722	    if (assignContext.s1GCache.firstTokenWithSinkNumber == 0) {
1723	        assignContext.curS2Idx++;
1724	        return;
1725	    }
1726	    uint32_t sinkBlockLastIndex =
1727	        (static_cast<uint32_t>(sinkNumber) + splitParam.s2BaseSize - 1) / splitParam.s2BaseSize - 1;
1728	    if (assignContext.curS2Idx < sinkBlockLastIndex ||
1729	        assignContext.curS2Idx >= assignContext.s1GCache.firstTokenWithSinkNumber) {
1730	        assignContext.curS2Idx++;
1731	        return;
1732	    }
1733	    if (assignContext.s1GCache.firstTokenWithSinkNumber <= sinkBlockLastIndex) {
1734	        assignContext.curS2Idx++;
1735	    } else {
1736	        assignContext.curS2Idx = assignContext.s1GCache.firstTokenWithSinkNumber;
1737	    }
1738	    return;
1739	}
1740	
1741	void AiInfraFusedInferAttentionSinkMetadataKernel::AssignByBlock(const SplitContext &splitContext,
1742	                                                                 AssignContext &assignContext)
1743	{
1744	    if (assignContext.isFinished) {
1745	        return;
1746	    }
1747	
1748	    int64_t curCost = assignContext.s1GCache.s1GNormalBlockCost;
1749	    if (assignContext.curS2Idx == (assignContext.s1GCache.s2End - 1U)) {
1750	        curCost = assignContext.s1GCache.s1GLastBlockCost;
1751	    }
1752	    uint32_t sinkNumber = (splitContext.baseInfo.keySinkNumber && splitContext.baseInfo.supportFD)
1753	                              ? splitContext.baseInfo.keySinkNumber
1754	                              : splitContext.baseInfo.sinkNumber;
1755	    while (IsWithinTolerance(assignContext.coreCache.costLimit,
1756	                             curCost / FA_TOLERANCE_RATIO,
1757	                             assignContext.coreCache.cost +
1758	                                 curCost)) { // (costLimit - curCostOnCore) * FA_TOLERANCE_RATIO > curCost；至少分配1块
1759	        assignContext.coreCache.cost += curCost;
1760	        assignContext.coreCache.block++;
1761	
1762	        if (sinkNumber > 0 &&
1763	            splitContext.baseInfo.sparseMode == 4U) { // AiInfraFusedInferAttentionSink自定义算子新增部分：更新curS2Idx
1764	            UpdateCurS2IdxWithSinkNumber(splitContext, assignContext, sinkNumber);
1765	        } else {
1766	            assignContext.curS2Idx++;
1767	        }
1768	        // 当前batch被分配一块出去，更新剩余负载
1769	        assignContext.bN2Cost = assignContext.bN2Cost - curCost;
1770	        // 当前行被分配一块出去，更新剩余负载
1771	        assignContext.s1GCache.s1GCost = assignContext.s1GCache.s1GCost - curCost;
1772	        assignContext.bN2Block--;
1773	        assignContext.s1GCache.s1GBlock--;
1774	    }
1775	}
