1777	void AiInfraFusedInferAttentionSinkMetadataKernel::ForceAssign(const SplitContext &splitContext,
1778	                                                               AssignContext &assignContext)
1779	{
1780	    if (assignContext.isFinished) {
1781	        return;
1782	    }
1783	
1784	    int64_t curCost = assignContext.s1GCache.s1GNormalBlockCost;
1785	    if (assignContext.curS2Idx == (assignContext.s1GCache.s2End - 1U)) {
1786	        curCost = assignContext.s1GCache.s1GLastBlockCost;
1787	    }
1788	
1789	    assignContext.coreCache.cost += curCost;
1790	    assignContext.coreCache.block++;
1791	    uint32_t sinkNumber = (splitContext.baseInfo.keySinkNumber && splitContext.baseInfo.supportFD)
1792	                              ? splitContext.baseInfo.keySinkNumber
1793	                              : splitContext.baseInfo.sinkNumber;
1794	    if (sinkNumber > 0 &&
1795	        splitContext.baseInfo.sparseMode == 4U) { // AiInfraFusedInferAttentionSink自定义算子新增部分：更新curS2Idx
1796	        UpdateCurS2IdxWithSinkNumber(splitContext, assignContext, sinkNumber);
1797	    } else {
1798	        assignContext.curS2Idx++;
1799	    }
1800	    // 当前batch被分配一块出去，更新剩余负载
1801	    assignContext.bN2Cost = assignContext.bN2Cost - curCost;
1802	    assignContext.bN2Block--;
1803	    // 当前行被分配一块出去，更新剩余负载
1804	    assignContext.s1GCache.s1GCost = assignContext.s1GCache.s1GCost - curCost;
1805	    assignContext.s1GCache.s1GBlock--;
1806	    UpdateCursor(splitContext, assignContext);
1807	}
1808	
1809	bool AiInfraFusedInferAttentionSinkMetadataKernel::IsNeedRecordFDInfo(const AssignContext &assignContext,
1810	                                                                      const SplitResult &splitRes)
1811	{
1812	    // 切分点大概率不会刚好在行尾，因此滞后处理归约信息的统计，到下一个切分点再判断是否需要归约
1813	    // 核0无需处理
1814	    if (assignContext.curCoreIdx == 0U) {
1815	        return false;
1816	    }
1817	    // 无跨核行，无需处理
1818	    if (assignContext.curKvSplitPart <= 1U) {
1819	        return false;
1820	    }
1821	    // 需要归约的行还未处理完
1822	    if (assignContext.curBN2Idx == splitRes.bN2End[assignContext.curCoreIdx - 1U] &&
1823	        assignContext.curS1GIdx == splitRes.gS1End[assignContext.curCoreIdx - 1U]) {
1824	        return false;
1825	    }
1826	    return true;
1827	}
1828	
1829	void AiInfraFusedInferAttentionSinkMetadataKernel::RecordFDInfo(const SplitContext &splitContext,
1830	                                                                const AssignContext &assignContext,
1831	                                                                SplitResult &result)
1832	{
1833	    const BaseInfo &baseInfo = splitContext.baseInfo;
1834	    const SplitParam &splitParam = splitContext.splitParam;
1835	    const SplitInfo &splitInfo = splitContext.splitInfo;
1836	    // 需要规约的行是上一个核的切分点所在位置
1837	    uint32_t splitBIdx = result.bN2End[assignContext.curCoreIdx - 1U] / baseInfo.n2Size;
1838	    uint32_t splitS1GIdx = result.gS1End[assignContext.curCoreIdx - 1U];
1839	    uint32_t s1Size = GetS1SeqSize(splitBIdx, baseInfo);
1840	
1841	    // 计算归约数据的FD均衡划分信息
1842	    uint32_t curFdS1gSize = (splitS1GIdx == splitInfo.s1GBaseNum[splitBIdx] - 1U)
1843	                                ? (s1Size * baseInfo.gSize - splitS1GIdx * splitParam.mBaseSize)
1844	                                : splitParam.mBaseSize;
1845	    uint32_t curFdS1gSplitPart = (curFdS1gSize + splitParam.gS1BaseSizeOfFd - 1U) / splitParam.gS1BaseSizeOfFd;
1846	    uint32_t curFdS1gLastPartSize = curFdS1gSize - (splitParam.gS1BaseSizeOfFd * (curFdS1gSplitPart - 1U));
1847	    // 记录
1848	    result.maxS2SplitNum = std::max(result.maxS2SplitNum, assignContext.curKvSplitPart);
1849	    // 若存在头归约，则切分点一定为上一个核结束的位置
1850	    result.fdRes.bN2IdxOfFdHead[result.numOfFdHead] = result.bN2End[assignContext.curCoreIdx - 1U];
1851	    result.fdRes.gS1IdxOfFdHead[result.numOfFdHead] = result.gS1End[assignContext.curCoreIdx - 1U];
1852	    result.fdRes.s2SplitNumOfFdHead[result.numOfFdHead] = assignContext.curKvSplitPart;
1853	    result.fdRes.gS1SplitNumOfFdHead[result.numOfFdHead] = curFdS1gSplitPart;
1854	    result.fdRes.gS1LastPartSizeOfFdHead[result.numOfFdHead] = curFdS1gLastPartSize;
1855	    result.numOfFdHead++;
1856	}
1857	
1858	void AiInfraFusedInferAttentionSinkMetadataKernel::CalcSplitPlan(uint32_t coreNum,
1859	                                                                 int64_t costLimit,
1860	                                                                 const SplitContext &splitContext,
1861	                                                                 SplitResult &result)
1862	{
1863	    const CostInfo &costInfo = splitContext.costInfo;
1864	    const BaseInfo &baseInfo = splitContext.baseInfo;
1865	
1866	    if (coreNum == 0U) {
1867	        return;
1868	    }
1869	    result.maxCost = 0U;
1870	    result.usedCoreNum = 0U;
1871	
1872	    AssignContext assignContext{};
1873	    assignContext.curBIdx = 0U;
1874	    assignContext.curS1GIdx = 0U;
1875	    assignContext.unassignedCost = costInfo.totalCost;
1876	    assignContext.bN2Cost = costInfo.bN2CostOfEachBatch[assignContext.curBIdx];
1877	    assignContext.bN2Block = costInfo.bN2BlockOfEachBatch[assignContext.curBIdx];
1878	    CalcBatchCache(assignContext.curBIdx, splitContext, assignContext.batchCache);
1879	    CalcS1GCache(assignContext.curS1GIdx, splitContext, assignContext.batchCache, assignContext.s1GCache);
1880	    assignContext.curS2Idx = assignContext.s1GCache.s2Start;
1881	
1882	    for (uint32_t i = 0; i < coreNum; ++i) {
1883	        if (result.maxCost > costLimit) {
1884	            return;
1885	        }
1886	        if (assignContext.isFinished || assignContext.unassignedCost <= 0) {
1887	            break;
1888	        }
1889	
1890	        assignContext.curCoreIdx = i;
1891	        result.fdRes.s2SplitStartIdxOfCore[assignContext.curCoreIdx] = assignContext.curKvSplitPart - 1U;
1892	
1893	        assignContext.coreCache = {};
1894	        assignContext.coreCache.costLimit = assignContext.unassignedCost / (coreNum - assignContext.curCoreIdx);
1895	
1896	        // 1、按整batch分配
1897	        AssignByBatch(splitContext, assignContext);
1898	        // 2、按行分配
1899	        AssignByRow(splitContext, assignContext);
1900	        if (baseInfo.supportFD && !baseInfo.batchInvariant) {
1901	            // 3、按块分配
1902	            AssignByBlock(splitContext, assignContext);
1903	            // 4、强制分配
1904	            if (assignContext.coreCache.block == 0) {
1905	                ForceAssign(splitContext, assignContext);
1906	            }
1907	        }
1908	        result.bN2End[i] = assignContext.curBN2Idx;
1909	        result.gS1End[i] = assignContext.curS1GIdx;
1910	        result.s2End[i] = assignContext.curS2Idx;
1911	        result.maxCost = std::max(result.maxCost, assignContext.coreCache.cost);
1912	
1913	        assignContext.unassignedCost -= assignContext.coreCache.cost;
1914	        if (baseInfo.supportFD && !baseInfo.batchInvariant) {
1915	            // 对之前的归约信息进行记录并清理
1916	            if (IsNeedRecordFDInfo(assignContext, result)) {
1917	                RecordFDInfo(splitContext, assignContext, result);
1918	                assignContext.curKvSplitPart = 1U;
1919	            }
1920	
1921	            // 更新S2切分信息
1922	            if (assignContext.curS2Idx > assignContext.s1GCache.s2Start &&
1923	                assignContext.curS2Idx <= assignContext.s1GCache.s2End) {
1924	                assignContext.curKvSplitPart++;
1925	            }
1926	        }
1927	    }
1928	    result.usedCoreNum = assignContext.curCoreIdx + 1;
1929	}
1930	
1931	void AiInfraFusedInferAttentionSinkMetadataKernel::SplitFD(SplitResult &result)
1932	{
1933	    uint32_t totalFDLoad = 0;
1934	    uint32_t totalFDHeadSplit = 0;
1935	    // 计算FD的总数据量
1936	    for (uint32_t i = 0; i < result.numOfFdHead; i++) {
1937	        totalFDLoad += result.fdRes.s2SplitNumOfFdHead[i] * result.fdRes.gS1SplitNumOfFdHead[i];
1938	        totalFDHeadSplit += result.fdRes.gS1SplitNumOfFdHead[i];
1939	    }
1940	
1941	    // 基于FA开核数量，计算每个Vector需要计算的FD数据量
1942	    // FD均衡的最小单位为一个归约任务的一个split，所以最多占用totalFDHeadSplit个vector
1943	    uint32_t maxVectorNum = std::min(totalFDHeadSplit, result.usedCoreNum * result.vecCubeRatio);
1944	    double loadThrOfVector =
1945	        static_cast<double>(totalFDLoad) / static_cast<double>(maxVectorNum); // 初始化vector的负载上限
1946	    int64_t loadOfCurVector = 0;
1947	    uint32_t curCoreIndex = 0;
1948	    uint32_t preTmpFDIndexEndOfFdHead = 0;
1949	    uint32_t preTmpFDIndexEndOfFdHeadSplit = 0;
1950	    for (uint32_t i = 0; i < result.numOfFdHead; i++) {
1951	        uint32_t fDKVSplitNum = result.fdRes.s2SplitNumOfFdHead[i];
1952	        for (uint32_t gS1SplitIdx = 0; gS1SplitIdx < result.fdRes.gS1SplitNumOfFdHead[i]; gS1SplitIdx++) {
1953	            double remainSpace = loadThrOfVector - static_cast<double>(loadOfCurVector); // 计算当前vector剩余负载空间
1954	            // 判断是否放在当前vector的标准是剩余空间是否能容纳一半当前归约块
1955	            if (fDKVSplitNum > remainSpace * FD_TOLERANCE_RATIO) {
1956	                result.fdRes.gS1IdxEndOfFdHead[curCoreIndex] = preTmpFDIndexEndOfFdHead;
1957	                result.fdRes.gS1IdxEndOfFdHeadSplit[curCoreIndex] = preTmpFDIndexEndOfFdHeadSplit;
1958	                curCoreIndex += 1U;
1959	                totalFDLoad -= static_cast<uint32_t>(loadOfCurVector); // 当前未分配的总负载
1960	                // 根据剩余负载和剩余可用vector更新负载上限，保证最后一个vector能分配所有负载
1961	                loadThrOfVector = static_cast<double>(totalFDLoad) / static_cast<double>(maxVectorNum - curCoreIndex);
1962	                loadOfCurVector = 0;
1963	            }
1964	            loadOfCurVector += fDKVSplitNum;
1965	            preTmpFDIndexEndOfFdHead = i;
1966	            preTmpFDIndexEndOfFdHeadSplit = gS1SplitIdx;
1967	        }
1968	    }
1969	    result.fdRes.gS1IdxEndOfFdHead[curCoreIndex] = preTmpFDIndexEndOfFdHead;
1970	    result.fdRes.gS1IdxEndOfFdHeadSplit[curCoreIndex] = preTmpFDIndexEndOfFdHeadSplit;
1971	    result.usedVecNumOfFd = curCoreIndex + 1;
1972	}
1973	
1974	void AiInfraFusedInferAttentionSinkMetadataKernel::SplitCore(uint32_t coreNum,
1975	                                                             const BaseInfo &baseInfo,
1976	                                                             const SplitParam &param,
1977	                                                             SplitResult &result)
1978	{
1979	    SplitContext splitContext(baseInfo, param);
1980	
1981	    // 1、划分基本块，统计信息
1982	    CalcSplitInfo(splitContext);
1983	    // 全空case
1984	    if (splitContext.splitInfo.isKvSeqAllZero) {
1985	        result.usedCoreNum = 1U;
1986	        result.bN2End[0] = baseInfo.bSize * baseInfo.n2Size;
1987	        result.gS1End[0] = 0U;
1988	        result.s2End[0] = 0U;
1989	        return;
1990	    }
1991	
1992	    CalcCostInfo(splitContext);
1993	
1994	    // 2、获取每个核的分配方案
1995	    uint32_t maxCore = std::min(coreNum, splitContext.costInfo.totalBlockNum);
1996	    uint32_t minCore =
1997	        static_cast<uint32_t>(std::sqrt(static_cast<float>(splitContext.costInfo.totalBlockNum) + 0.25f) + 0.5f);
1998	    minCore = std::min(minCore, maxCore);
1999	
2000	    result.maxCost = INT64_MAX;
2001	    result.usedCoreNum = 1U;
2002	
2003	    SplitResult tmpResult{coreNum, result.vecCubeRatio};
2004	    for (uint32_t i = minCore; i <= maxCore; ++i) {
2005	        CalcSplitPlan(i, result.maxCost, splitContext, tmpResult);
2006	        if (tmpResult.maxCost < result.maxCost) {
2007	            CopyTmpResult(tmpResult, result);
2008	        }
2009	        ClearTmpResult(tmpResult);
2010	    }
2011	
2012	    // 3、存在FD任务，对FD进行负载均衡分配
2013	    if (result.numOfFdHead > 0U) {
2014	        SplitFD(result);
2015	    }
2016	    result.usedCoreNum = std::max(result.usedCoreNum, 1U); // 至少使用1个core
2017	}
2018	
2019	REGISTER_CPU_KERNEL(AI_INFRA_FUSED_INFER_ATTENTION_SINK_METADATA, AiInfraFusedInferAttentionSinkMetadataKernel);
2020	}  // namespace aicpu

