constexpr uint32_t S_INNER_SIZE_1024 = 1024;

constexpr uint32_t S1_SIZE_16 = 16;
constexpr uint32_t MAX_SPLIT_SIZE = 8192;

constexpr uint32_t M_BASE_SIZE_32 = 32;
constexpr uint32_t M_BASE_SIZE_64 = 64;
constexpr uint32_t M_BASE_SIZE_128 = 128;
constexpr uint32_t M_BASE_SIZE_256 = 256;
constexpr uint32_t M_BASE_SIZE_512 = 512;

constexpr uint32_t S_INNER_SIZE_ALIGN_512 = 512;
constexpr uint32_t S_INNER_SIZE_ALIGN_1024 = 1024;
constexpr uint32_t S_INNER_SIZE_ALIGN_2048 = 2048;
constexpr uint32_t S_INNER_SIZE_ALIGN_4096 = 4096;

enum class BlockType : uint32_t {
    NORMAL_BLOCK = 0,
    TAIL_BLOCK,
    BLOCK_MAX_TYPE
};

enum class SparseMode : uint8_t {
    DEFAULT_MASK = 0,
    ALL_MASK,
    LEFT_UP_CAUSAL,
    RIGHT_DOWN_CAUSAL,
    BAND,
};

template <class T> using Range = std::pair<T, T>;

template <class T>
using BlockCost = std::array<std::array<T, static_cast<size_t>(BlockType::BLOCK_MAX_TYPE)>,
                             static_cast<size_t>(BlockType::BLOCK_MAX_TYPE)>;

template <typename T> static inline T Clip(T value, T minValue, T maxValue)
{
    if (value < minValue) {
        return minValue;
    }
    if (value > maxValue) {
        return maxValue;
    }
    return value;
}

template <typename T> static inline auto Align(T num, T rnd) -> T
{
    return (((rnd) == 0) ? 0 : (((num) + (rnd)-1) / (rnd) * (rnd)));
}

template <typename T> static inline bool IsWithinTolerance(T limit, T tolerance, T value)
{
    return limit + tolerance >= value;
}

// 分核功能模块输出：FD信息，包含需要归约的数据索引及其分核信息
struct FlashDecodeResult {
    // 1、归约任务的索引信息
    std::vector<uint32_t> bN2IdxOfFdHead{}; // 每个归约任务的BN2索引，脚标为归约任务的序号，最大为核数-1
    std::vector<uint32_t> gS1IdxOfFdHead{}; // 每个归约任务的GS1索引，脚标为归约任务的序号
    std::vector<uint32_t> s2SplitNumOfFdHead{}; // 每个归约任务的S2核间切分份数，脚标为归约任务的序号
    // 2、FD负载均衡阶段，归约任务的分核（vec）信息
    std::vector<uint32_t> gS1SplitNumOfFdHead{}; // 每个归约任务m轴切分份数，脚标为归约任务的序号
    std::vector<uint32_t> gS1LastPartSizeOfFdHead{}; // 每个归约任务m轴切分的最后一份的大小，脚标为归约任务的序号
    std::vector<uint32_t>
        gS1IdxEndOfFdHead{}; // FD负载均衡阶段，每个vector的一级索引，脚标为vector ID，值为归约任务的ID
    std::vector<uint32_t>
        gS1IdxEndOfFdHeadSplit{}; // FD负载均衡阶段，每个vector的二级索引，脚标为vector ID，值为归约任务的m轴切分ID
    // 3、每个core处理的第1个归约任务的数据应存放的workspace位置
    std::vector<uint32_t> s2SplitStartIdxOfCore{};
    FlashDecodeResult(uint32_t coreNum, uint32_t vecCubeRatio)
        : bN2IdxOfFdHead(coreNum), gS1IdxOfFdHead(coreNum), s2SplitNumOfFdHead(coreNum), gS1SplitNumOfFdHead(coreNum),
          gS1LastPartSizeOfFdHead(coreNum), gS1IdxEndOfFdHead(coreNum * vecCubeRatio),
          gS1IdxEndOfFdHeadSplit(coreNum * vecCubeRatio), s2SplitStartIdxOfCore(coreNum)
    {}
};

// 分核功能模块输出：FA阶段的核间分核信息
struct SplitResult {
    uint32_t usedCoreNum{0U}; // 使用的核数量
    uint32_t vecCubeRatio{0U}; // vec 与 cube 核数比例
    std::vector<uint32_t> bN2End{}; // 每个核处理数据的BN2结束点
    std::vector<uint32_t> gS1End{}; // 每个核处理数据的GS1结束点
    std::vector<uint32_t> s2End{}; // 每个核处理数据的S2结束点
    int64_t maxCost{0}; // 慢核开销
    uint32_t numOfFdHead{0U}; // 归约任务数量
    uint32_t maxS2SplitNum{0U}; // 单个归约任务最大分核数量
    uint32_t usedVecNumOfFd{0U}; // 归约过程使用的vector数量
    FlashDecodeResult fdRes{0U, 0U}; // FD信息
    SplitResult(uint32_t coreNum, uint32_t ratio)
        : bN2End(coreNum), vecCubeRatio(ratio), gS1End(coreNum), s2End(coreNum), fdRes(coreNum, ratio){};
};

// 分核功能模块输入：输入case的基本信息
struct BaseInfo {
    uint32_t bSize{0U};
    uint32_t n2Size{0U};
    uint32_t gSize{0U};
    uint32_t s1Size{0U};
    uint32_t s2Size{0U};
    bool isS1G{true};
    bool isAccumSeqS1{false};
    bool isAccumSeqS2{false};
