#ifdef __cplusplus
extern "C" {
#endif

namespace {
static aclnnStatus ParamsCheck(const aclTensor *actualSeqLengthsOptional,
                               const aclTensor *actualSeqLengthsKvOptional,
                               int64_t numHeadsQ,
                               int64_t numHeadsKv,
                               int64_t headDimQk,
                               int64_t headDimV,
                               int64_t batchSizeOptional,
                               int64_t sparseModeOptional,
                               int64_t preTokensOptional,
                               int64_t nextTokensOptional,
                               char *inputLayoutOptional,
                               char *inputLayoutKvOptional,
                               int64_t sinkNumOptional,
                               int64_t kSinkNumOptional,
                               int64_t ropeHeadDimOptional,
                               int64_t blockSizeOptional,
                               int64_t aicCoreNumOptional,
                               int64_t aivCoreNumOptional,
                               const aclTensor *metaData)
{
    return ACLNN_SUCCESS;
}

aclnnStatus aclnnAiInfraFusedInferAttentionSinkMetadataGetWorkspaceSize(const aclTensor *actualSeqLengthsOptional,
                                                                        const aclTensor *actualSeqLengthsKvOptional,
                                                                        int64_t numHeadsQ,
                                                                        int64_t numHeadsKv,
                                                                        int64_t headDimQk,
                                                                        int64_t headDimV,
                                                                        int64_t batchSizeOptional,
                                                                        int64_t sparseModeOptional,
                                                                        int64_t preTokensOptional,
                                                                        int64_t nextTokensOptional,
                                                                        char *inputLayoutOptional,
                                                                        char *inputLayoutKvOptional,
                                                                        int64_t sinkNumOptional,
                                                                        int64_t kSinkNumOptional,
                                                                        int64_t ropeHeadDimOptional,
                                                                        int64_t blockSizeOptional,
                                                                        int64_t aicCoreNumOptional,
                                                                        int64_t aivCoreNumOptional,
                                                                        const aclTensor *metaData,
                                                                        uint64_t *workspaceSize,
                                                                        aclOpExecutor **executor)
{
    L2_DFX_PHASE_1(aclnnAiInfraFusedInferAttentionSinkMetadata,
                   DFX_IN(actualSeqLengthsOptional,
                          actualSeqLengthsKvOptional,
                          numHeadsQ,
                          numHeadsKv,
                          headDimQk,
                          headDimV,
                          batchSizeOptional,
                          sparseModeOptional,
                          preTokensOptional,
                          nextTokensOptional,
                          inputLayoutOptional,
                          inputLayoutKvOptional,
                          sinkNumOptional,
                          kSinkNumOptional,
                          ropeHeadDimOptional,
                          blockSizeOptional,
                          aicCoreNumOptional,
                          aivCoreNumOptional),
                   DFX_OUT(metaData));

    auto uniqueExecutor = CREATE_EXECUTOR();
    CHECK_RET(uniqueExecutor.get() != nullptr, ACLNN_ERR_INNER_CREATE_EXECUTOR);

    auto ret = ParamsCheck(actualSeqLengthsOptional,
                                     actualSeqLengthsKvOptional,
                                     numHeadsQ,
                                     numHeadsKv,
                                     headDimQk,
                                     headDimV,
                                     batchSizeOptional,
                                     sparseModeOptional,
                                     preTokensOptional,
                                     nextTokensOptional,
                                     inputLayoutOptional,
                                     inputLayoutKvOptional,
                                     sinkNumOptional,
                                     kSinkNumOptional,
                                     ropeHeadDimOptional,
                                     blockSizeOptional,
                                     aicCoreNumOptional,
                                     aivCoreNumOptional,
                                     metaData);
    CHECK_RET(ret == ACLNN_SUCCESS, ret);

    const op::PlatformInfo &npuInfo = op::GetCurrentPlatformInfo();
    const char *socVersion = npuInfo.GetSocLongVersion().c_str();
    uint32_t aicCoreNum = npuInfo.GetCubeCoreNum();
    uint32_t aivCoreNum = npuInfo.GetVectorCoreNum();

    if (aicCoreNumOptional <= 0 || aicCoreNumOptional > static_cast<int64_t>(aicCoreNum)) {
        aicCoreNumOptional = static_cast<int64_t>(aicCoreNum);
    }
    if (aivCoreNumOptional <= 0 || aivCoreNumOptional > static_cast<int64_t>(aivCoreNum)) {
        aivCoreNumOptional = static_cast<int64_t>(aivCoreNum);
    }
    auto output = l0op::AiInfraFusedInferAttentionSinkMetadata(actualSeqLengthsOptional,
                                                               actualSeqLengthsKvOptional,
                                                               numHeadsQ,
                                                               numHeadsKv,
                                                               headDimQk,
                                                               headDimV,
                                                               batchSizeOptional,
                                                               sparseModeOptional,
                                                               preTokensOptional,
                                                               nextTokensOptional,
                                                               inputLayoutOptional,
                                                               inputLayoutKvOptional,
                                                               sinkNumOptional,
                                                               kSinkNumOptional,
                                                               false,
                                                               ropeHeadDimOptional,
                                                               blockSizeOptional,
                                                               socVersion,
                                                               aicCoreNumOptional,
                                                               aivCoreNumOptional,
                                                               metaData,
                                                               uniqueExecutor.get());
    CHECK_RET(output != nullptr, ACLNN_ERR_INNER_NULLPTR);

    *workspaceSize = 0;
    uniqueExecutor.ReleaseTo(executor);
    return ACLNN_SUCCESS;
}

__attribute__((visibility("default"))) aclnnStatus aclnnAiInfraFusedInferAttentionSinkMetadata(void *workspace,
                                                                                               uint64_t workspaceSize,
                                                                                               aclOpExecutor *executor,
                                                                                               aclrtStream stream)
{
    L2_DFX_PHASE_2(aclnnAiInfraFusedInferAttentionSinkMetadata);
    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
}
}

