#define KERNEL_STATUS_OK      0
#define KERNEL_STATUS_PARAM_INVALID 1

namespace aicpu {
template <typename T>
inline typename std::enable_if<std::is_integral_v<T>, bool>::type GetAttrValue(
  CpuKernelContext &ctx, const std::string &name, T &value)
{
  auto attr = ctx.GetAttr(name);
  if (!attr) {
    KERNEL_LOG_ERROR("attr is null: %s", name.c_str());
    return false;
  }
  value = static_cast<T>(attr->GetInt());
  return true;
}

inline bool GetAttrValue(CpuKernelContext &ctx, const std::string &name,
                         std::string &value)
{
  auto attr = ctx.GetAttr(name);
  if (!attr) {
    KERNEL_LOG_ERROR("attr is null: %s", name.c_str());
    return false;
  }
  value = attr->GetString();
  return true;
}

inline bool GetAttrValue(CpuKernelContext &ctx, const std::string &name,
                         bool &value)
{
  auto attr = ctx.GetAttr(name);
  if (!attr) {
    KERNEL_LOG_ERROR("attr is null: %s", name.c_str());
    return false;
  }
  value = attr->GetBool();
  return true;
}

template <typename T>
inline typename std::enable_if<std::is_integral_v<T>, void>::type GetAttrValueOpt(CpuKernelContext &ctx, 
  const std::string &name, T &value)
{
  auto attr = ctx.GetAttr(name);
  if (attr != nullptr) {
    value = static_cast<T>(attr->GetInt());
  }
}

inline void GetAttrValueOpt(CpuKernelContext &ctx, const std::string &name,
                            std::string &value)
{
  auto attr = ctx.GetAttr(name);
  if (attr != nullptr) {
    value = attr->GetString();
  }
}

inline void GetAttrValueOpt(CpuKernelContext &ctx, const std::string &name,
                            bool &value)
{
  auto attr = ctx.GetAttr(name);
  if (attr != nullptr) {
    value = attr->GetBool();
  }
}

} // namespace aicpu

